INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (577, 577, 'en', 'Hand dryer', 'Hand dryer, SS304, Electronic Infra-red Sensing, Brushed Finish 1. Body Material: S.S 304. 2. Voltage: 220–240V 3. Frequency: 50/60Hz. 4. Total Power: 300–700W 5. Motor Power: 300W. 6. RPM: 50000 7. Electrical Isolation: Class I…', 'Hand dryer, SS304, Electronic Infra-red Sensing, Brushed Finish\n1. Body Material: S.S 304. 2. Voltage: 220–240V\n3. Frequency: 50/60Hz. 4. Total Power: 300–700W\n5. Motor Power: 300W. 6. RPM: 50000\n7. Electrical Isolation: Class I. \n8. Hot & Cold Switch: Yes. 9. Current: 3.5A\n10. Air Speed: 100 m/s. \n13. Air Temperature (10 cm distance / 21°C): 38°C\n14. Net Weight: 4.5 kg. 15. Noise Level in dB (at 2m): 70 dB. 16. Water Splash Proof: IPX4. 17. Auto Cutoff: 60 seconds\n\nVerified drawing dimensions:\nOverall width: 230 mm\nOverall depth: 100 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (578, 578, 'en', 'Automatic hand dryer', 'Automatic hand dryer, Drying time: 5-7 Seconds, Rated Power (W): 1800W, Material: ABS. Rated Power: 1800/2000W, Wall mount, Air Speed: 18m/s', 'Automatic hand dryer, Drying time: 5-7 Seconds, Rated Power (W): 1800W, Material: ABS. Rated Power: 1800/2000W, Wall mount, Air Speed: 18m/s\n\nVerified drawing dimensions:\nOverall width: 235 mm\nOverall depth: 215 mm\nOverall height: 240 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (579, 579, 'en', 'Hand Dryer', 'Hand Dryer, durable hand dryer with a stainless steel body. It has an intelligent heating system that saves energy by adjusting to room temperature, adding heat only when it drops below 25°C. Technical Specs: •Voltage: 220–240V…', 'Hand Dryer, durable hand dryer with a stainless steel body. It has an intelligent heating system that saves energy by adjusting to room temperature, adding heat only when it drops below 25°C.\nTechnical Specs: •Voltage: 220–240V\n•Power: 800–1650W , •Air Speed: 95 m/s\n•Motor RPM: 21000 , •Weight: 12.5 kg\n•Dimensions: 300 x 730 x 222 mm\n•Noise: 72 dB at 2 meters, •Water Splash Protection: IPX4\n•Auto Cutoff: 30 seconds');
