INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (718, 3, 'cs', 'Stojící WC mísa s hlubokým splachováním', 'Stojící WC mísa s hlubokým splachováním, zadní odpad (P-trap), vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, kompletní se sladěnou splachovací nádržkou, sedátko s poklopem, splachovací mechanismus, vtokové a odtokové…', 'Stojící WC mísa s hlubokým splachováním, zadní odpad (P-trap), vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, kompletní se sladěnou splachovací nádržkou, sedátko s poklopem, splachovací mechanismus, vtokové a odtokové armatury a montážní sada.\n\nOvěřené rozměry z technického výkresu:\nDélka: 700 mm\nŠířka: 370 mm\nVýška: 855 mm');
