INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (721, 5, 'tr', 'Monoblok Tek Parça Yerden Klozet', 'Monoblok Tek Parça Yerden Klozet, alttan çıkış (S-sifon): 250mm aks mesafesi, pürüzsüz sırlı birinci sınıf vitrifiye seramikten üretilmiştir, rezervuar iç takımı, giriş/çıkış bağlantı parçaları ve montaj takımı, Geberit iç takım…', 'Monoblok Tek Parça Yerden Klozet, alttan çıkış (S-sifon): 250mm aks mesafesi, pürüzsüz sırlı birinci sınıf vitrifiye seramikten üretilmiştir, rezervuar iç takımı, giriş/çıkış bağlantı parçaları ve montaj takımı, Geberit iç takım mekanizmalı, toplam ölçü: 700x360x810mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (722, 5, 'cs', 'Stojící monoblokové WC s hlubokým splachováním', 'Stojící monoblokové WC s hlubokým splachováním, spodní odpad (S-trap): 250mm osová rozteč odpadu, vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, splachovací mechanismus, vtokové a odtokové armatury a montážní sada, se…', 'Stojící monoblokové WC s hlubokým splachováním, spodní odpad (S-trap): 250mm osová rozteč odpadu, vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, splachovací mechanismus, vtokové a odtokové armatury a montážní sada, se splachovacím mechanismem Geberit, celkový rozměr: 700x360x810mm');
