INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (725, 7, 'tr', 'İki Parçalı Rezervuarlı Yerden Klozet', 'İki Parçalı Rezervuarlı Yerden Klozet, alttan çıkış (S-sifon): 250mm aks mesafesi, pürüzsüz sırlı birinci sınıf vitrifiye seramikten üretilmiştir, uyumlu seramik rezervuar dahil, klozet kapağı, rezervuar iç takımı, giriş/çıkış…', 'İki Parçalı Rezervuarlı Yerden Klozet, alttan çıkış (S-sifon): 250mm aks mesafesi, pürüzsüz sırlı birinci sınıf vitrifiye seramikten üretilmiştir, uyumlu seramik rezervuar dahil, klozet kapağı, rezervuar iç takımı, giriş/çıkış bağlantı parçaları ve montaj takımı, Geberit iç takım mekanizmalı, toplam ölçü: 710x390x765mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (726, 7, 'cs', 'Stojící dvoudílné kombinační WC', 'Stojící dvoudílné kombinační WC, spodní odpad (S-trap): 250mm osová rozteč odpadu, vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, kompletní se sladěnou splachovací nádržkou, sedátko s poklopem, splachovací…', 'Stojící dvoudílné kombinační WC, spodní odpad (S-trap): 250mm osová rozteč odpadu, vyrobeno z prvotřídní sanitární keramiky s hladkou glazurou, kompletní se sladěnou splachovací nádržkou, sedátko s poklopem, splachovací mechanismus, vtokové a odtokové armatury a montážní sada, se splachovacím mechanismem Geberit, celkový rozměr: 710x390x765mm');
