INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (733, 11, 'tr', 'Çocuk Klozet Kapağı', 'Çocuk Klozet Kapağı paslanmaz metal menteşe, üstten montajlı, yavaş kapanır.', 'Çocuk Klozet Kapağı\npaslanmaz metal menteşe, üstten montajlı, yavaş kapanır.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 386 mm\nGenişlik: 354 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (734, 11, 'cs', 'Dětské WC sedátko', 'Dětské WC sedátko kovové panty, horní upevnění, s tichým dovíráním.', 'Dětské WC sedátko\nkovové panty, horní upevnění, s tichým dovíráním.\n\nOvěřené rozměry z technického výkresu:\nDélka: 386 mm\nŠířka: 354 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (735, 12, 'tr', 'Akıllı Entegre Bide Fonksiyonlu Monoblok Klozet', 'Akıllı Entegre Bide Fonksiyonlu Monoblok Klozet, zemine monte, kanalsız hijyenik tasarım, beyaz vitrifiye seramik, yavaş kapanır klozet kapağı, entegre akıllı bide yıkama sistemi, otomatik yıkama, doğrudan şebeke bağlantılı…', 'Akıllı Entegre Bide Fonksiyonlu Monoblok Klozet, zemine monte, kanalsız hijyenik tasarım, beyaz vitrifiye seramik, yavaş kapanır klozet kapağı, entegre akıllı bide yıkama sistemi, otomatik yıkama, doğrudan şebeke bağlantılı rezervuar gerektirmeyen akıllı klozet, gömme veya açık rezervuar gerektirmez; yıkama hacmi proje su tüketimi şartnamesine göre ayarlanabilir.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 680 mm\nGenişlik: 412 mm\nYükseklik: 515 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (736, 12, 'cs', 'Chytré monoblokové WC s integrovanou bidetovou funkcí', 'Chytré monoblokové WC s integrovanou bidetovou funkcí, podlahová montáž, bezokrajové provedení Rimless, bílá sanitární keramika, WC sedátko s tichým dovíráním, integrovaný inteligentní bidetový systém, automatické splachování…', 'Chytré monoblokové WC s integrovanou bidetovou funkcí, podlahová montáž, bezokrajové provedení Rimless, bílá sanitární keramika, WC sedátko s tichým dovíráním, integrovaný inteligentní bidetový systém, automatické splachování, chytré WC s přímým napojením na vodu (bez nádržky), nevyžaduje podomítkovou ani nástěnnou splachovací nádržku; objem splachování lze nastavit dle projektových požadavků.\n\nOvěřené rozměry z technického výkresu:\nDélka: 680 mm\nŠířka: 412 mm\nVýška: 515 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (737, 13, 'tr', 'Akıllı Klozet Sistemi', 'Akıllı Klozet Sistemi, seramik gövdeli tip, yavaş kapanır klozet kapağı, çok fonksiyonlu, zemine monte.', 'Akıllı Klozet Sistemi, seramik gövdeli tip, yavaş kapanır klozet kapağı, çok fonksiyonlu, zemine monte.');
