INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (817, 53, 'tr', 'Paslanmaz Çelik Alaturka Hela Taşı', 'Paslanmaz Çelik Alaturka Hela Taşı Malzeme: birinci sınıf AISI 304 paslanmaz çelik, ayna parlaklığında polisajlı yüzey, yatay gider çıkışı, entegre su perdeli koku sifonu, kaymaz ayak basma yüzeyli, ağır hizmet tipi ticari sınıf…', 'Paslanmaz Çelik Alaturka Hela Taşı \nMalzeme: birinci sınıf AISI 304 paslanmaz çelik, ayna parlaklığında polisajlı yüzey, yatay gider çıkışı, entegre su perdeli koku sifonu, kaymaz ayak basma yüzeyli, ağır hizmet tipi ticari sınıf, tüm standart montaj aksesuarları dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 625 mm\nGenişlik: 595 mm\nYükseklik: 208 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (818, 53, 'cs', 'Nerezová turecká dřepací toaleta', 'Nerezová turecká dřepací toaleta Materiál: prémiová nerezová ocel AISI 304, zrcadlově leštěný povrch, vodorovný odpadní vývod, integrovaná vodní pachová uzávěrka, protiskluzové nášlapy, vysokozátěžové komerční provedení, včetně…', 'Nerezová turecká dřepací toaleta \nMateriál: prémiová nerezová ocel AISI 304, zrcadlově leštěný povrch, vodorovný odpadní vývod, integrovaná vodní pachová uzávěrka, protiskluzové nášlapy, vysokozátěžové komerční provedení, včetně veškerého standardního upevnění.\n\nOvěřené rozměry z technického výkresu:\nDélka: 625 mm\nŠířka: 595 mm\nVýška: 208 mm');
