INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (899, 94, 'tr', 'Duvara Monte Pisuvar Ara Bölme Panosu', 'Duvara Monte Pisuvar Ara Bölme Panosu, kompakt HPL laminat panel, suya ve neme dayanıklı, AISI 304 paslanmaz çelik montaj elemanları, uygunluk: umumi ve ticari banyolar, okullar ve eğitim kurumları, otel ve ticari yapılar.', 'Duvara Monte Pisuvar Ara Bölme Panosu, kompakt HPL laminat panel, suya ve neme dayanıklı, AISI 304 paslanmaz çelik montaj elemanları, uygunluk: umumi ve ticari banyolar, okullar ve eğitim kurumları, otel ve ticari yapılar.\n\nDoğrulanmış teknik çizim ölçüleri:\nYükseklik: 600 mm\nGenişlik: 350 mm\nKalınlık: 12 mm');
