INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1043, 166, 'tr', 'Banyo Aynası', 'Banyo Aynası, 6 mm kalınlığında ayna camı, arka askı aparatlı, rodajlı parlak kenar, siyah alüminyum çerçeveli, Ölçü: 800x650mm', 'Banyo Aynası, 6 mm kalınlığında ayna camı, arka askı aparatlı, rodajlı parlak kenar, siyah alüminyum çerçeveli, Ölçü: 800x650mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1044, 166, 'cs', 'Koupelnové zrcadlo', 'Koupelnové zrcadlo, zrcadlové sklo tloušťky 6 mm, zadní závěsné úchyty, leštěná hrana, s černým hliníkovým rámem, Rozměr: 800x650mm', 'Koupelnové zrcadlo, zrcadlové sklo tloušťky 6 mm, zadní závěsné úchyty, leštěná hrana, s černým hliníkovým rámem, Rozměr: 800x650mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1045, 167, 'tr', 'Paslanmaz Çelik Çerçeveli Güvenlik Aynası', '1. Paslanmaz Çelik Çerçeveli Güvenlik Aynası 2. güvenlik filmi kaplamalı 5. arka yüzey güvenlik filmli 4. Ölçü: 650x800mm', '1. Paslanmaz Çelik Çerçeveli Güvenlik Aynası\n2. güvenlik filmi kaplamalı\n5. arka yüzey güvenlik filmli\n4. Ölçü: 650x800mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1046, 167, 'cs', 'Bezpečnostní nerezové zrcadlo', '1. Bezpečnostní nerezové zrcadlo 2. s bezpečnostní fólií 5. zadní bezpečnostní fólie 4. Rozměr: 650x800mm', '1. Bezpečnostní nerezové zrcadlo\n2. s bezpečnostní fólií\n5. zadní bezpečnostní fólie\n4. Rozměr: 650x800mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1047, 168, 'tr', 'Alüminyum Çerçeveli Banyo Aynası', '1. 6 mm ayna camı 2. 4 mm alüminyum çerçeveli ayna 3. siyah eloksal alüminyum çerçeve 4. arka yüzey güvenlik filmli 5. Ölçü: 650x800mm', '1. 6 mm ayna camı \n2. 4 mm alüminyum çerçeveli ayna\n3. siyah eloksal alüminyum çerçeve\n4. arka yüzey güvenlik filmli\n5. Ölçü: 650x800mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1048, 168, 'cs', 'Koupelnové zrcadlo s hliníkovým rámem', '1. 6mm zrcadlo 2. zrcadlo se 4mm hliníkovým rámem 3. černý hliníkový rám 4. zadní bezpečnostní fólie 5. Rozměr: 650x800mm', '1. 6mm zrcadlo \n2. zrcadlo se 4mm hliníkovým rámem\n3. černý hliníkový rám\n4. zadní bezpečnostní fólie\n5. Rozměr: 650x800mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1049, 169, 'tr', 'Sensör Aydınlatmalı LED Banyo Aynası', 'Sensör Aydınlatmalı LED Banyo Aynası, 6 mm kalınlığında ayna camı, arkadan aydınlatmalı desen, üç renk ışık modu, 3000-6000K, tek dokunuşlu sensör anahtarı, renk sıcaklığı değişimi ve parlaklık kısma (dimmer)', 'Sensör Aydınlatmalı LED Banyo Aynası, 6 mm kalınlığında ayna camı, arkadan aydınlatmalı desen, üç renk ışık modu, 3000-6000K, tek dokunuşlu sensör anahtarı, renk sıcaklığı değişimi ve parlaklık kısma (dimmer)');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1050, 169, 'cs', 'Koupelnové LED zrcadlo se senzorovým osvětlením', 'Koupelnové LED zrcadlo se senzorovým osvětlením, zrcadlové sklo tloušťky 6 mm, podsvícený motiv, tři režimy barvy světla, 3000-6000K, jednodotykový senzorový spínač, změna barvy světla a stmívání', 'Koupelnové LED zrcadlo se senzorovým osvětlením, zrcadlové sklo tloušťky 6 mm, podsvícený motiv, tři režimy barvy světla, 3000-6000K, jednodotykový senzorový spínač, změna barvy světla a stmívání');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1051, 170, 'tr', 'Bronz Çerçeveli Banyo Aynası', 'Bronz Çerçeveli Banyo Aynası, yuvarlatılmış köşeli premium tasarım ve yüksek kaliteli gümüş ayna camı, gizli duvar montaj aparatları dahil, gizli LED aydınlatma dahil.', 'Bronz Çerçeveli Banyo Aynası, yuvarlatılmış köşeli premium tasarım ve yüksek kaliteli gümüş ayna camı, gizli duvar montaj aparatları dahil, gizli LED aydınlatma dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 1000 mm\nGenişlik: 850 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1052, 170, 'cs', 'Koupelnové zrcadlo s bronzovým rámem', 'Koupelnové zrcadlo s bronzovým rámem, prémiové provedení se zaoblenými rohy a vysoce kvalitním stříbrným zrcadlovým sklem, kompletní se skrytým nástěnným upevněním, včetně skrytého LED osvětlení.', 'Koupelnové zrcadlo s bronzovým rámem, prémiové provedení se zaoblenými rohy a vysoce kvalitním stříbrným zrcadlovým sklem, kompletní se skrytým nástěnným upevněním, včetně skrytého LED osvětlení.\n\nOvěřené rozměry z technického výkresu:\nDélka: 1000 mm\nŠířka: 850 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1053, 171, 'tr', 'Mat Siyah Çerçeveli Banyo Aynası', 'Mat Siyah Çerçeveli Banyo Aynası, yuvarlatılmış köşeli premium tasarım ve yüksek kaliteli gümüş ayna camı, gizli duvar montaj aparatları dahil, gizli LED aydınlatma dahil.', 'Mat Siyah Çerçeveli Banyo Aynası, yuvarlatılmış köşeli premium tasarım ve yüksek kaliteli gümüş ayna camı, gizli duvar montaj aparatları dahil, gizli LED aydınlatma dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 1000 mm\nGenişlik: 850 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1054, 171, 'cs', 'Koupelnové zrcadlo s matně černým rámem', 'Koupelnové zrcadlo s matně černým rámem, prémiové provedení se zaoblenými rohy a vysoce kvalitním stříbrným zrcadlovým sklem, kompletní se skrytým nástěnným upevněním, včetně skrytého LED osvětlení.', 'Koupelnové zrcadlo s matně černým rámem, prémiové provedení se zaoblenými rohy a vysoce kvalitním stříbrným zrcadlovým sklem, kompletní se skrytým nástěnným upevněním, včetně skrytého LED osvětlení.\n\nOvěřené rozměry z technického výkresu:\nDélka: 1000 mm\nŠířka: 850 mm');
