INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1059, 174, 'tr', 'Engelli Uyumlu Açılı Banyo Aynası', 'Engelli Uyumlu Açılı Banyo Aynası, gizli askı aparatlı duvar montajı, AISI 304 paslanmaz çelik, saten / fırçalanmış yüzey, yuvarlatılmış köşeler.', 'Engelli Uyumlu Açılı Banyo Aynası, gizli askı aparatlı duvar montajı, AISI 304 paslanmaz çelik, saten / fırçalanmış yüzey, yuvarlatılmış köşeler.\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 870 mm\nGenişlik: 460 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1060, 174, 'cs', 'Bezbariérové sklopné koupelnové zrcadlo', 'Bezbariérové sklopné koupelnové zrcadlo, nástěnná montáž se skrytými závěsy, nerezová ocel AISI 304, saténový / broušený povrch, zaoblené rohy.', 'Bezbariérové sklopné koupelnové zrcadlo, nástěnná montáž se skrytými závěsy, nerezová ocel AISI 304, saténový / broušený povrch, zaoblené rohy.\n\nOvěřené rozměry z technického výkresu:\nDélka: 870 mm\nŠířka: 460 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1061, 175, 'tr', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası, 8", çift taraflı (1X / 3X büyüteçli), eklemli katlanır uzatma kolu, SMD LED aydınlatma, dokunmatik anahtar, USB şarjlı & AC 110–260V güç kaynağı, pirinç, çinko ve paslanmaz çelik…', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası, 8", çift taraflı (1X / 3X büyüteçli), eklemli katlanır uzatma kolu, SMD LED aydınlatma, dokunmatik anahtar, USB şarjlı & AC 110–260V güç kaynağı, pirinç, çinko ve paslanmaz çelik konstrüksiyon, krom yüzey, montaj aksesuarları dahil\n\nDoğrulanmış teknik çizim ölçüleri:\nAyna çapı: 200 mm\nKol uzunluğu: 415 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1062, 175, 'cs', 'Nástěnné kosmetické LED zrcátko', 'Nástěnné kosmetické LED zrcátko, 8", oboustranné (zvětšení 1× / 3×), kloubové výsuvné rameno, SMD LED osvětlení, dotykový spínač, dobíjení přes USB & AC 110–260V napájení, konstrukce z mosazi, zinku a nerezové oceli, chromový…', 'Nástěnné kosmetické LED zrcátko, 8", oboustranné (zvětšení 1× / 3×), kloubové výsuvné rameno, SMD LED osvětlení, dotykový spínač, dobíjení přes USB & AC 110–260V napájení, konstrukce z mosazi, zinku a nerezové oceli, chromový povrch, včetně montážního příslušenství\n\nOvěřené rozměry z technického výkresu:\nPrůměr zrcadla: 200 mm\nDélka ramene: 415 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1063, 176, 'tr', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası, 7", çift taraflı (1X / 3X büyüteçli), krom yüzey, eklemli katlanır uzatma kolu, 360° dönebilen ayna başlığı, ayna üzerinde dokunmatik sensör anahtarı, LED aydınlatma, pilli kullanım (4 ×…', 'Duvara Monte LED Aydınlatmalı Makyaj Aynası, 7", çift taraflı (1X / 3X büyüteçli), krom yüzey, eklemli katlanır uzatma kolu, 360° dönebilen ayna başlığı, ayna üzerinde dokunmatik sensör anahtarı, LED aydınlatma, pilli kullanım (4 × AAA), gizli şarj bağlantılı, pirinç, çinko ve paslanmaz çelik konstrüksiyon, üçlü güç besleme seçeneği: pil + USB + adaptör şarjı, montaj aksesuarları dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nAyna çapı: 175 mm\nBirinci kol bölümü: 200 mm\nİkinci kol bölümü: 90 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1064, 176, 'cs', 'Nástěnné kosmetické LED zrcátko', 'Nástěnné kosmetické LED zrcátko, 7", oboustranné (zvětšení 1× / 3×), chromový povrch, kloubové výsuvné rameno, hlava zrcadla otočná o 360°, dotykový spínač na ploše zrcadla, LED osvětlení, bateriový provoz (4 × AAA), skryté…', 'Nástěnné kosmetické LED zrcátko, 7", oboustranné (zvětšení 1× / 3×), chromový povrch, kloubové výsuvné rameno, hlava zrcadla otočná o 360°, dotykový spínač na ploše zrcadla, LED osvětlení, bateriový provoz (4 × AAA), skryté nabíjecí připojení, mosaz, konstrukce ze zinku a nerezové oceli, tři způsoby napájení: baterie + USB + síťový adaptér, včetně montážního příslušenství.\n\nOvěřené rozměry z technického výkresu:\nPrůměr zrcadla: 175 mm\nPrvní rameno: 200 mm\nDruhé rameno: 90 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1065, 177, 'tr', 'Engelli WC Destekli Sırt Dayama Ünitesi', 'Engelli WC Destekli Sırt Dayama Ünitesi, sırt dayama pedi, engelli duvar tutunma barları için paslanmaz çelik güvenlikli sırt dayama ünitesi', 'Engelli WC Destekli Sırt Dayama Ünitesi, sırt dayama pedi, engelli duvar tutunma barları için paslanmaz çelik güvenlikli sırt dayama ünitesi\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 560 mm\nSırt dayama genişliği: 280 mm\nSırt dayama yüksekliği: 160 mm\nAyarlanabilir çıkıntı mesafesi: 234–284 mm\nSırt dayama kalınlığı: 25 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1066, 177, 'cs', 'Polstrovaná opěrka zad pro bezbariérové WC', 'Polstrovaná opěrka zad pro bezbariérové WC, opěrka zad, nerezová bezpečnostní opěrka zad pro nástěnná bezbariérová madla', 'Polstrovaná opěrka zad pro bezbariérové WC, opěrka zad, nerezová bezpečnostní opěrka zad pro nástěnná bezbariérová madla\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 560 mm\nŠířka opěrky zad: 280 mm\nVýška opěrky zad: 160 mm\nNastavitelné vyložení: 234–284 mm\nTloušťka opěrky zad: 25 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1067, 178, 'tr', 'Duvara Monte Tutunma Barı', 'Duvara Monte Tutunma Barı, katlanır, Yüzey: çelik Malzeme: paslanmaz çelik, polimer plastik Taşıma kapasitesi [kg]: 150', 'Duvara Monte Tutunma Barı, katlanır, Yüzey: çelik\nMalzeme: paslanmaz çelik, polimer plastik\nTaşıma kapasitesi [kg]: 150\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 600 mm');
