INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1079, 184, 'tr', 'Engelli WC Katlanır Tutunma Barı', 'Engelli WC Katlanır Tutunma Barı, SUS304 paslanmaz çelik konstrüksiyon ile fırçalanmış krom yüzey, entegre tuvalet kâğıdı tutuculu ağır hizmet katlanır tasarım', 'Engelli WC Katlanır Tutunma Barı, SUS304 paslanmaz çelik konstrüksiyon ile fırçalanmış krom yüzey, entegre tuvalet kâğıdı tutuculu ağır hizmet katlanır tasarım\n\nDoğrulanmış teknik çizim ölçüleri:\nUzunluk: 700 mm\nYükseklik: 185 mm\nDuvar aynası ölçüsü: 220 × 120 × 5 mm\nBoru çapı: 32 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1080, 184, 'cs', 'Sklopné bezbariérové madlo k WC', 'Sklopné bezbariérové madlo k WC, konstrukce z nerezové oceli SUS304 s broušený chromový povrch, sklopné vysokozátěžové provedení s integrovaným držákem toaletního papíru', 'Sklopné bezbariérové madlo k WC, konstrukce z nerezové oceli SUS304 s broušený chromový povrch, sklopné vysokozátěžové provedení s integrovaným držákem toaletního papíru\n\nOvěřené rozměry z technického výkresu:\nDélka: 700 mm\nVýška: 185 mm\nKrycí nástěnná deska: 220 × 120 × 5 mm\nPrůměr trubky: 32 mm');
