INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1095, 192, 'tr', '', 'Çerçeve / Şase: alüminyum yarım çerçeveli ve cam ön panelli Hazne: 50 yıl ömürlü şişirme HDPE gövde Mekanizma: pirinç valf ve SS304 paslanmaz hortum bağlantı seti: duvara asma klozet için eksiksiz takım pnömatik çift kademeli yıkama', 'Çerçeve / Şase: alüminyum yarım çerçeveli ve cam ön panelli\nHazne: 50 yıl ömürlü şişirme HDPE gövde\nMekanizma: pirinç valf ve SS304 paslanmaz hortum\nbağlantı seti: duvara asma klozet için eksiksiz takım\npnömatik çift kademeli yıkama\n\nDoğrulanmış teknik çizim ölçüleri:\nYükseklik: 1000 mm\nGenişlik: 480 mm\nDerinlik: 120 mm');
