INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1133, 211, 'tr', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli, çift kademeli yıkama (manuel ve otomatik), paslanmaz çelik yüzey su tasarruf sistemi, tüm bağlantı aksesuarlarıyla eksiksiz proje şartnamelerine tam uyumlu.', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli, çift kademeli yıkama (manuel ve otomatik), paslanmaz çelik yüzey\nsu tasarruf sistemi, tüm bağlantı aksesuarlarıyla eksiksiz \nproje şartnamelerine tam uyumlu.\n\nDoğrulanmış teknik çizim ölçüleri:\nGenişlik: 164 mm\nYükseklik: 244 mm\nDerinlik: 13.5 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1134, 211, 'cs', 'Senzorové ovládací tlačítko pro podomítkovou nádržku', 'Senzorové ovládací tlačítko pro podomítkovou nádržku, dvojité splachování (manuální i automatické), nerezový povrch úsporný vodní systém, kompletní včetně veškerého příslušenství v souladu s projektovými specifikacemi.', 'Senzorové ovládací tlačítko pro podomítkovou nádržku, dvojité splachování (manuální i automatické), nerezový povrch\núsporný vodní systém, kompletní včetně veškerého příslušenství \nv souladu s projektovými specifikacemi.\n\nOvěřené rozměry z technického výkresu:\nŠířka: 164 mm\nVýška: 244 mm\nHloubka: 13.5 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1135, 212, 'tr', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli, otomatik çift kademeli yıkama cam yüzey, ince tasarım, tüm bağlantı aksesuarlarıyla eksiksiz proje şartnamelerine tam uyumlu.', 'Gömme Rezervuar İçin Sensörlü Kumanda Paneli, otomatik çift kademeli yıkama\ncam yüzey, ince tasarım, tüm bağlantı aksesuarlarıyla eksiksiz \nproje şartnamelerine tam uyumlu.\n\nDoğrulanmış teknik çizim ölçüleri:\nDerinlik: 5.5 mm\nGenişlik: 228 mm\nYükseklik: 144 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1136, 212, 'cs', 'Senzorové ovládací tlačítko pro podomítkovou nádržku', 'Senzorové ovládací tlačítko pro podomítkovou nádržku, automatické dvojité splachování skleněný povrch, štíhlé provedení, kompletní včetně veškerého příslušenství v souladu s projektovými specifikacemi.', 'Senzorové ovládací tlačítko pro podomítkovou nádržku, automatické dvojité splachování\nskleněný povrch, štíhlé provedení, kompletní včetně veškerého příslušenství \nv souladu s projektovými specifikacemi.\n\nOvěřené rozměry z technického výkresu:\nHloubka: 5.5 mm\nŠířka: 228 mm\nVýška: 144 mm');
