INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1471, 380, 'tr', 'Tek Kollu Lavabo Bataryası', 'Tek Kollu Lavabo Bataryası, tezgâh üstü, SUS 316 paslanmaz çelik gövde, elmas dokulu pirinç kumanda kolu ve gaga ucu, rose gold + açık gunmetal dekoratif yüzey, 3.35# KEROX seramik kartuş, NEOPERL perlatör, TUCAI WaterMark…', 'Tek Kollu Lavabo Bataryası, tezgâh üstü, SUS 316 paslanmaz çelik gövde, elmas dokulu pirinç kumanda kolu ve gaga ucu, rose gold + açık gunmetal dekoratif yüzey, 3.35# KEROX seramik kartuş, NEOPERL perlatör, TUCAI WaterMark paslanmaz çelik esnek bağlantı hortumları\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 200 mm\nGaga uzanım mesafesi: 143 mm\nGaga çıkış yüksekliği: 75 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1472, 380, 'cs', 'Jednopáková umyvadlová baterie', 'Jednopáková umyvadlová baterie, stojánková montáž, tělo z nerezové oceli SUS 316, mosazná páka a ústí výtoku s diamantovým vroubkováním, dekorativní povrch růžové zlato + světlý gunmetal, 3.35# keramická kartuše KEROX, perlátor…', 'Jednopáková umyvadlová baterie, stojánková montáž, tělo z nerezové oceli SUS 316, mosazná páka a ústí výtoku s diamantovým vroubkováním, dekorativní povrch růžové zlato + světlý gunmetal, 3.35# keramická kartuše KEROX, perlátor NEOPERL, flexibilní nerezové hadice TUCAI WaterMark\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 200 mm\nDosah výtoku: 143 mm\nVýška výtoku: 75 mm');
