INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1507, 398, 'tr', 'Duvar Tipi Temassız Sensörlü Sıvı Sabunluk Gagası', 'entegre kızılötesi sensörlü duvar tipi temassız sıvı sabunluk gagası, parlak ayna krom yüzey ve ankastre montaj. ankastre sabun pompası ve hazne sistemine bağlantı için tasarlanmıştır.sabun tipi: sıvı sabun', 'entegre kızılötesi sensörlü duvar tipi temassız sıvı sabunluk gagası, parlak ayna krom yüzey ve ankastre montaj. ankastre sabun pompası ve hazne sistemine bağlantı için tasarlanmıştır.sabun tipi: sıvı sabun\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 125 mm\nGövde uzunluğu: 120 mm\nDış çap: 45 mm\nİç çap: 32 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1508, 398, 'cs', 'Nástěnný bezdotykový senzorový dávkovač tekutého mýdla', 'nástěnný bezdotykový dávkovač tekutého mýdla s integrovaným infračerveným senzorem, leštěný zrcadlově chromový povrch a podomítková instalace. navrženo pro připojení k podomítkovému čerpadlu a zásobníku mýdla.typ mýdla: tekuté mýdlo', 'nástěnný bezdotykový dávkovač tekutého mýdla s integrovaným infračerveným senzorem, leštěný zrcadlově chromový povrch a podomítková instalace. navrženo pro připojení k podomítkovému čerpadlu a zásobníku mýdla.typ mýdla: tekuté mýdlo\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 125 mm\nDélka tělesa: 120 mm\nVnější průměr: 45 mm\nVnitřní průměr: 32 mm');
