INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1569, 429, 'tr', 'Duvar Tipi Kızılötesi Sensörlü Abdest Bataryası', 'Duvar Tipi Kızılötesi Sensörlü Abdest Bataryası, birinci sınıf AISI 304 paslanmaz çelik, parlak ayna krom yüzey, LUFLY patentli Nano enerji teknolojisi, geleneksel pil gerektirmez, elektrik tesisatı gerektirmez, Maks. 150000…', 'Duvar Tipi Kızılötesi Sensörlü Abdest Bataryası, birinci sınıf AISI 304 paslanmaz çelik, parlak ayna krom yüzey, LUFLY patentli Nano enerji teknolojisi, geleneksel pil gerektirmez, elektrik tesisatı gerektirmez, Maks. 150000 açma-kapama çevrimi, su tasarruflu perlatör, standart montaj aksesuarları dahil\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 227 mm\nGövde uzunluğu: 190 mm\nGövde yüksekliği: 28 mm\nGövde çapı: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1570, 429, 'cs', 'Nástěnná automatická infračervená omývací baterie', 'Nástěnná automatická infračervená omývací baterie, prémiová nerezová ocel AISI 304, zrcadlově chromový povrch, patentovaná nano-energetická technologie LUFLY, bez klasické baterie, bez nutnosti elektrického připojení, Až 150000…', 'Nástěnná automatická infračervená omývací baterie, prémiová nerezová ocel AISI 304, zrcadlově chromový povrch, patentovaná nano-energetická technologie LUFLY, bez klasické baterie, bez nutnosti elektrického připojení, Až 150000 sepnutí, úsporný perlátor, včetně standardního montážního příslušenství\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 227 mm\nDélka tělesa: 190 mm\nVýška tělesa: 28 mm\nPrůměr tělesa: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1571, 430, 'tr', 'Ankastre Duvar Tipi Kızılötesi Sensörlü Lavabo Bataryası', 'Ankastre Duvar Tipi Kızılötesi Sensörlü Lavabo Bataryası, birinci sınıf AISI 304 paslanmaz çelik, parlak ayna krom yüzey, su tasarruflu perlatör, ankastre sıva altı kutusu ve standart montaj aksesuarları dahil', 'Ankastre Duvar Tipi Kızılötesi Sensörlü Lavabo Bataryası, birinci sınıf AISI 304 paslanmaz çelik, parlak ayna krom yüzey, su tasarruflu perlatör, ankastre sıva altı kutusu ve standart montaj aksesuarları dahil\n\nDoğrulanmış teknik çizim ölçüleri:\nGaga çıkıntı mesafesi: 205 mm\nGaga çıkış yüksekliği: 21 mm\nDuvar aynası çapı: 158 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1572, 430, 'cs', 'Podomítková nástěnná infračervená senzorová baterie', 'Podomítková nástěnná infračervená senzorová baterie, prémiová nerezová ocel AISI 304, zrcadlově chromový povrch, úsporný perlátor, kompletní včetně podomítkového boxu a standardního montážního příslušenství', 'Podomítková nástěnná infračervená senzorová baterie, prémiová nerezová ocel AISI 304, zrcadlově chromový povrch, úsporný perlátor, kompletní včetně podomítkového boxu a standardního montážního příslušenství\n\nOvěřené rozměry z technického výkresu:\nVyložení výtoku: 205 mm\nVýška výtoku: 21 mm\nPrůměr nástěnné rozety: 158 mm');
