INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1623, 456, 'tr', 'Tekli Havluluk', 'Tekli Havluluk, masif pirinç gövde yapısı ile PVD rose gold yüzey, gizli montaj sistemli duvar tipi. prestijli banyo projelerine uygun modern kare tasarım.', 'Tekli Havluluk, masif pirinç gövde yapısı ile PVD rose gold yüzey, gizli montaj sistemli duvar tipi. prestijli banyo projelerine uygun modern kare tasarım.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 600 mm\nTaban genişliği: 65 mm\nTaban yüksekliği: 30 mm\nBar yüksekliği: 15 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1624, 456, 'cs', 'Jednoduchý držák ručníků', 'Jednoduchý držák ručníků, masivní mosazná konstrukce s povrch PVD růžové zlato, nástěnná montáž se skrytým upevněním. moderní čtvercový design vhodný pro prémiové koupelnové realizace.', 'Jednoduchý držák ručníků, masivní mosazná konstrukce s povrch PVD růžové zlato, nástěnná montáž se skrytým upevněním. moderní čtvercový design vhodný pro prémiové koupelnové realizace.\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 600 mm\nŠířka základny: 65 mm\nVýška základny: 30 mm\nVýška tyče: 15 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1625, 457, 'tr', 'Yuvarlak Rozetli Havlu Askı Barı', 'Yuvarlak Rozetli Havlu Askı Barı,SS#304, içeriği: paslanmaz çelik vida ve dübel seti, parlak yüzey', 'Yuvarlak Rozetli Havlu Askı Barı,SS#304, içeriği: paslanmaz çelik vida ve dübel seti, parlak yüzey\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 225 mm\nToplam yükseklik: 135 mm\nKumanda kolu genişliği: 55 mm\nKumanda kolu yüksekliği: 38 mm');
