INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1753, 521, 'tr', 'El Yapımı Paslanmaz Çelik Mutfak Evyesi', 'El Yapımı Paslanmaz Çelik Mutfak Evyesi, fırçalanmış saten yüzeyli birinci sınıf SUS304 paslanmaz çelikten üretilmiştir. X-kanallı hızlı tahliye sistemine sahip modern tek hazneli tasarım, ses yalıtım pedleri, R10 yuvarlatılmış iç…', 'El Yapımı Paslanmaz Çelik Mutfak Evyesi, fırçalanmış saten yüzeyli birinci sınıf SUS304 paslanmaz çelikten üretilmiştir. X-kanallı hızlı tahliye sistemine sahip modern tek hazneli tasarım, ses yalıtım pedleri, R10 yuvarlatılmış iç köşeler\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 700 mm\nToplam derinlik: 400 mm\nToplam yükseklik: 200 mm\nİç hazne ölçüsü: 650 × 350 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1754, 521, 'cs', 'Ručně vyráběný nerezový kuchyňský dřez', 'Ručně vyráběný nerezový kuchyňský dřez, vyrobeno z prémiové nerezové oceli SUS304 s broušeným saténovým povrchem. moderní jednodřezové provedení s odtokovým X-drážkováním, protihlukové podložky, zaoblené rohy R10', 'Ručně vyráběný nerezový kuchyňský dřez, vyrobeno z prémiové nerezové oceli SUS304 s broušeným saténovým povrchem. moderní jednodřezové provedení s odtokovým X-drážkováním, protihlukové podložky, zaoblené rohy R10\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 700 mm\nCelková hloubka: 400 mm\nCelková výška: 200 mm\nVnitřní rozměr mísy: 650 × 350 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1755, 522, 'tr', 'Sifon Takımlı Mutfak Evyesi', 'Sifon Takımlı Mutfak Evyesi, süzgeç malzemesi SS304 paslanmaz çelik + polimer.', 'Sifon Takımlı Mutfak Evyesi, süzgeç malzemesi SS304 paslanmaz çelik + polimer.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 810 mm\nToplam derinlik: 510 mm\nHazne genişliği: 355 mm\nHazne derinliği: 410 mm');
