INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1805, 547, 'tr', 'Tezgâh İçi Gömme Döner Kapaklı Mutfak Çöp Kovası', 'Tezgâh İçi Gömme Döner Kapaklı Mutfak Çöp Kovası, gizli temizlik haznesi, askılı sallanır kapak döner kapaklı tip, Yapı: kapaklı döner kapaklı tip, Malzeme: paslanmaz çelik Form: Yuvarlak, döner kapak, Büyük boy, parmak izi…', 'Tezgâh İçi Gömme Döner Kapaklı Mutfak Çöp Kovası, gizli temizlik haznesi, askılı sallanır kapak\ndöner kapaklı tip, Yapı: kapaklı\ndöner kapaklı tip, Malzeme: paslanmaz çelik\nForm: Yuvarlak, döner kapak, Büyük boy, parmak izi bırakmayan yüzey\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 302 mm\nKapak çapı: 190 mm\nKapak ağız çapı: 152 mm\nGövde çapı: 157 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1806, 547, 'cs', 'Vestavný kuchyňský odpadkový koš do pracovní desky s výklopným víkem', 'Vestavný kuchyňský odpadkový koš do pracovní desky s výklopným víkem, skrytá čisticí nádoba, výkyvné víko provedení s otočným víkem, Konstrukce: s víkem provedení s otočným víkem, Materiál: nerezová ocel Tvar: Kulatý, výklopné…', 'Vestavný kuchyňský odpadkový koš do pracovní desky s výklopným víkem, skrytá čisticí nádoba, výkyvné víko\nprovedení s otočným víkem, Konstrukce: s víkem\nprovedení s otočným víkem, Materiál: nerezová ocel\nTvar: Kulatý, výklopné víko, Velké provedení, úprava proti otiskům prstů\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 302 mm\nPrůměr víka: 190 mm\nPrůměr otvoru víka: 152 mm\nPrůměr tělesa: 157 mm');
