INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1864, 576, 'cs', 'Automatický osoušeč rukou', 'Automatický osoušeč rukou, SS304, elektronické infračervené snímání, lesklý povrch 1, Napětí: 220V~50HZ 2, příkon:1400W 3, rychlost proudění vzduchu: 150m/s 4, doba sušení: 10-12 s 5, stupeň krytí: IPX3 6, Proud: 8A 7, automatické…', 'Automatický osoušeč rukou, SS304, elektronické infračervené snímání, lesklý povrch\n1, Napětí: 220V~50HZ\n2, příkon:1400W \n3, rychlost proudění vzduchu: 150m/s\n4, doba sušení: 10-12 s\n5, stupeň krytí: IPX3\n6, Proud: 8A\n7, automatické senzorové snímání\n8, bezpečnostní časovač: 60S\n9, RPM: 30001\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 234 mm\nCelková výška: 392 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1865, 577, 'tr', 'Otomatik El Kurutma Makinesi', 'Otomatik El Kurutma Makinesi, SS304, elektronik kızılötesi sensör algılama, fırçalanmış yüzey 1. Gövde Malzeme: S.S 304. 2. Gerilim: 220–240V 3. Frekans: 50/60Hz. 4. Toplam güç: 300–700W 5. Motor gücü: 300W. 6. RPM: 50000 7…', 'Otomatik El Kurutma Makinesi, SS304, elektronik kızılötesi sensör algılama, fırçalanmış yüzey\n1. Gövde Malzeme: S.S 304. 2. Gerilim: 220–240V\n3. Frekans: 50/60Hz. 4. Toplam güç: 300–700W\n5. Motor gücü: 300W. 6. RPM: 50000\n7. elektrik yalıtım sınıfı: Sınıf I. \n8. sıcak ve soğuk hava anahtarı: Evet. 9. Akım: 3.5A\n10. hava hızı: 100 m/s. \n13. hava sıcaklığı (10 cm mesafe / 21°C): 38°C\n14. net ağırlık: 4.5 kg. 15. ses seviyesi (dB) ((2 m mesafede)): 70 dB. 16. su sıçrama koruması: IPX4. 17. otomatik kapanma: 60 saniye\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 230 mm\nToplam derinlik: 100 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1866, 577, 'cs', 'Automatický osoušeč rukou', 'Automatický osoušeč rukou, SS304, elektronické infračervené snímání, broušený povrch 1. Těleso Materiál: S.S 304. 2. Napětí: 220–240V 3. Frekvence: 50/60Hz. 4. Celkový příkon: 300–700W 5. Výkon motoru: 300W. 6. RPM: 50000 7. třída…', 'Automatický osoušeč rukou, SS304, elektronické infračervené snímání, broušený povrch\n1. Těleso Materiál: S.S 304. 2. Napětí: 220–240V\n3. Frekvence: 50/60Hz. 4. Celkový příkon: 300–700W\n5. Výkon motoru: 300W. 6. RPM: 50000\n7. třída elektrické izolace: Třída I. \n8. přepínač teplého a studeného vzduchu: Ano. 9. Proud: 3.5A\n10. rychlost vzduchu: 100 m/s. \n13. teplota vzduchu (10 cm vzdálenost / 21°C): 38°C\n14. čistá hmotnost: 4.5 kg. 15. hladina hluku v dB ((ve 2 m)): 70 dB. 16. odolnost proti stříkající vodě: IPX4. 17. automatické vypnutí: 60 sekund\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 230 mm\nCelková hloubka: 100 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1867, 578, 'tr', 'Otomatik El Kurutma Makinesi', 'Otomatik El Kurutma Makinesi, kurutma süresi: 5-7 saniye, anma gücü (W): 1800W, Malzeme: ABS. anma gücü: 1800/2000W, duvara monte, hava hızı: 18m/s', 'Otomatik El Kurutma Makinesi, kurutma süresi: 5-7 saniye, anma gücü (W): 1800W, Malzeme: ABS. anma gücü: 1800/2000W, duvara monte, hava hızı: 18m/s\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 235 mm\nToplam derinlik: 215 mm\nToplam yükseklik: 240 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1868, 578, 'cs', 'Automatický osoušeč rukou', 'Automatický osoušeč rukou, doba sušení: 5-7 sekund, jmenovitý výkon (W): 1800W, Materiál: ABS. jmenovitý výkon: 1800/2000W, nástěnná montáž, rychlost vzduchu: 18m/s', 'Automatický osoušeč rukou, doba sušení: 5-7 sekund, jmenovitý výkon (W): 1800W, Materiál: ABS. jmenovitý výkon: 1800/2000W, nástěnná montáž, rychlost vzduchu: 18m/s\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 235 mm\nCelková hloubka: 215 mm\nCelková výška: 240 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1869, 579, 'tr', 'Otomatik El Kurutma Makinesi', 'Otomatik El Kurutma Makinesi, paslanmaz çelik gövdeli dayanıklı el kurutma makinesi; oda sıcaklığına göre enerji tasarrufu sağlayan akıllı ısıtma sistemi, yalnızca 25°C altına düştüğünde ısıtmayı devreye alır. teknik özellikler…', 'Otomatik El Kurutma Makinesi, paslanmaz çelik gövdeli dayanıklı el kurutma makinesi; oda sıcaklığına göre enerji tasarrufu sağlayan akıllı ısıtma sistemi, yalnızca 25°C altına düştüğünde ısıtmayı devreye alır.\nteknik özellikler: •Gerilim: 220–240V\n•Güç: 800–1650W, •hava hızı: 95 m/s\n•Motor RPM: 21000, •Ağırlık: 12.5 kg\n•Ölçüler: 300 x 730 x 222 mm\n•Ses seviyesi: 72 dB (2 metrede), •su sıçrama koruması: IPX4\n•otomatik kapanma: 30 saniye');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1870, 579, 'cs', 'Automatický osoušeč rukou', 'Automatický osoušeč rukou, odolný osoušeč rukou s nerezovým tělem a inteligentním topným systémem šetřícím energii podle pokojové teploty, ohřev spíná pouze při poklesu teploty pod 25 °C. technické parametry: •Napětí: 220–240V…', 'Automatický osoušeč rukou, odolný osoušeč rukou s nerezovým tělem a inteligentním topným systémem šetřícím energii podle pokojové teploty, ohřev spíná pouze při poklesu teploty pod 25 °C.\ntechnické parametry: •Napětí: 220–240V\n•Výkon: 800–1650W, •rychlost vzduchu: 95 m/s\n•Motor RPM: 21000, •Hmotnost: 12.5 kg\n•Rozměry: 300 x 730 x 222 mm\n•Hlučnost: 72 dB (ve 2 metrech), •ochrana proti stříkající vodě: IPX4\n•automatické vypnutí: 30 sekund');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1871, 580, 'tr', 'Ankastre Gömme Paslanmaz Çelik Sensörlü El Kurutma Makinesi', 'Ankastre Gömme Paslanmaz Çelik Sensörlü El Kurutma Makinesi, Malzeme AISI 304 paslanmaz çelik, toplam ölçü 575*320*164, kesim ölçüsü 550*310*135, Kalınlık 1.2mm, fırçalanmış yüzey, anma gücü 220AC, giriş gücü 605W; hava üfleme hızı…', 'Ankastre Gömme Paslanmaz Çelik Sensörlü El Kurutma Makinesi, Malzeme AISI 304 paslanmaz çelik, toplam ölçü 575*320*164, kesim ölçüsü 550*310*135, Kalınlık 1.2mm, fırçalanmış yüzey, anma gücü 220AC, giriş gücü 605W; hava üfleme hızı 65m/s; ısıtma gücü 230W; algılama mesafesi 12-15mm; su geçirmezlik sınıfı IPX4');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1872, 580, 'cs', 'Zapuštěný nerezový automatický senzorový osoušeč rukou', 'Zapuštěný nerezový automatický senzorový osoušeč rukou, Materiál nerezová ocel AISI 304, celkový rozměr 575*320*164, montážní otvor 550*310*135, Tloušťka 1.2mm, kartáčovaný povrch, jmenovitý výkon 220AC, vstupní příkon 605W…', 'Zapuštěný nerezový automatický senzorový osoušeč rukou, Materiál nerezová ocel AISI 304, celkový rozměr 575*320*164, montážní otvor 550*310*135, Tloušťka 1.2mm, kartáčovaný povrch, jmenovitý výkon 220AC, vstupní příkon 605W; rychlost proudění vzduchu 65m/s; topný výkon 230W; snímací vzdálenost 12-15mm; stupeň voděodolnosti IPX4');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1873, 581, 'tr', 'Ankastre Gömme Kâğıt Havlu Dispenseri ve Çöp Kovası Ünitesi', 'Ankastre Gömme Kâğıt Havlu Dispenseri ve Çöp Kovası Ünitesi, AISI 304 paslanmaz çelik, fırçalanmış saten yüzey, kilitlenebilir kâğıt havlu dispenseri dahil, açık raf, entegre çöp kovası bölmesi ve paslanmaz çelik anahtarlı kilit…', 'Ankastre Gömme Kâğıt Havlu Dispenseri ve Çöp Kovası Ünitesi, AISI 304 paslanmaz çelik, fırçalanmış saten yüzey, kilitlenebilir kâğıt havlu dispenseri dahil, açık raf, entegre çöp kovası bölmesi ve paslanmaz çelik anahtarlı kilit sistemi.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam ölçü: 340 × 750 × 140 mm\nİç gövde ölçüsü: 320 × 715 × 130 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1874, 581, 'cs', 'Zapuštěná kombinovaná jednotka zásobníku ručníků a odpadkového koše', 'Zapuštěná kombinovaná jednotka zásobníku ručníků a odpadkového koše, nerezová ocel AISI 304, broušený saténový povrch, včetně uzamykatelného zásobníku papírových ručníků, otevřená polička, přihrádka odpadkového koše a nerezové…', 'Zapuštěná kombinovaná jednotka zásobníku ručníků a odpadkového koše, nerezová ocel AISI 304, broušený saténový povrch, včetně uzamykatelného zásobníku papírových ručníků, otevřená polička, přihrádka odpadkového koše a nerezové cylindrické zámky.\n\nOvěřené rozměry z technického výkresu:\nCelkový rozměr: 340 × 750 × 140 mm\nVnitřní těleso: 320 × 715 × 130 mm');
