INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1889, 589, 'tr', 'Yarı Gömme Duvar Tipi Paslanmaz Çöp Ünitesi', 'Yarı Gömme Duvar Tipi Paslanmaz Çöp Ünitesi, özel üretim, 304 kalite paslanmaz çelik, fırçalanmış saten yüzey, silindir kilitli ön servis kapağı, iç paslanmaz çelik kancalarla sabitlenen çıkarılabilir ağır hizmet vinil iç hazne…', 'Yarı Gömme Duvar Tipi Paslanmaz Çöp Ünitesi, özel üretim, 304 kalite paslanmaz çelik, fırçalanmış saten yüzey, silindir kilitli ön servis kapağı, iç paslanmaz çelik kancalarla sabitlenen çıkarılabilir ağır hizmet vinil iç hazne (45,5 L kapasite), montaj donanımı dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 340 mm\nToplam yükseklik: 1196 mm\nToplam derinlik: 130 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1890, 589, 'cs', 'Polozapuštěný nástěnný odpadkový koš', 'Polozapuštěný nástěnný odpadkový koš, zakázková výroba, nerezová ocel třídy 304, broušený saténový povrch, uzamykatelná čelní dvířka s cylindrickým zámkem, vyjímatelná odolná vinylová vložka (objem 45,5 l) uchycená vnitřními…', 'Polozapuštěný nástěnný odpadkový koš, zakázková výroba, nerezová ocel třídy 304, broušený saténový povrch, uzamykatelná čelní dvířka s cylindrickým zámkem, vyjímatelná odolná vinylová vložka (objem 45,5 l) uchycená vnitřními nerezovými háčky, včetně montážního kování.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 340 mm\nCelková výška: 1196 mm\nCelková hloubka: 130 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1891, 590, 'tr', 'Duş Bataryası', 'Duş Bataryası, zaman ayarlı otomatik kapanan, ankastre, sıcak-soğuk batarya, ankastre sıva altı kutusu dahil, Yüzey: krom, batarya tipi: basmalı zaman ayarlı montaj tipi: ankastre', 'Duş Bataryası, zaman ayarlı otomatik kapanan, ankastre, sıcak-soğuk batarya, ankastre sıva altı kutusu dahil, Yüzey: krom, batarya tipi: basmalı zaman ayarlı\nmontaj tipi: ankastre\n\nDoğrulanmış teknik çizim ölçüleri:\nRozet plakası çapı: 150 mm\nÖn çıkıntı mesafesi: 28 mm\nGömme montaj derinliği: 65 mm\nMontaj deliği çapı: 62 mm\nKumanda aks aralığı: 65 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1892, 590, 'cs', 'Sprchová baterie', 'Sprchová baterie, samouzavírací, podomítková, směšovací baterie, včetně podomítkového boxu, Povrch: chrom, typ baterie: tlačná způsob montáže: podomítková', 'Sprchová baterie, samouzavírací, podomítková, směšovací baterie, včetně podomítkového boxu, Povrch: chrom, typ baterie: tlačná\nzpůsob montáže: podomítková\n\nOvěřené rozměry z technického výkresu:\nPrůměr krycí desky: 150 mm\nPřední vyložení: 28 mm\nZápustná hloubka: 65 mm\nPrůměr montážního otvoru: 62 mm\nRozteč ovládání: 65 mm');
