INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1895, 592, 'tr', 'Dijital Ekranlı 2/3 Yollu Pirinç Ankastre Duş Yönlendirici Batarya', 'Dijital Ekranlı 2/3 Yollu Pirinç Ankastre Duş Yönlendirici Batarya, mat siyah renk, Malzeme: pirinç, kartuş malzemesi: seramik, Özellik: termostatik batarya, çift kollu, tepe duşu formu: Kare, su geçirmez dijital sıcaklık ekranlı…', 'Dijital Ekranlı 2/3 Yollu Pirinç Ankastre Duş Yönlendirici Batarya, mat siyah renk, Malzeme: pirinç, kartuş malzemesi: seramik, Özellik: termostatik batarya, çift kollu, tepe duşu formu: Kare, su geçirmez dijital sıcaklık ekranlı\nkartuş ömrü: 500000 kullanım çevrimi, Fonksiyon:\n1.3 yollu\n2.termostatik\n3.her fonksiyon ayrı ayrı veya birlikte çalışabilir\n\nDoğrulanmış teknik çizim ölçüleri:\nRozet plakası genişliği: 130 mm\nRozet plakası yüksekliği: 220 mm\nToplam derinlik: 80 mm\nGövde yüksekliği: 200 mm\nArka derinlik: 10 mm');
