INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1899, 594, 'tr', 'Ankastre Yan Vücut Duş Jetleri', 'Ankastre Yan Vücut Duş Jetleri, su tasarruflu, masajlı vücut duş jetleri, ABS polimer malzeme, kare form, krom kaplamalı', 'Ankastre Yan Vücut Duş Jetleri, su tasarruflu, masajlı vücut duş jetleri, ABS polimer malzeme, kare form, krom kaplamalı\n\nDoğrulanmış teknik çizim ölçüleri:\nDış ölçü: 145 × 145 mm\nToplam derinlik: 95 mm\nİç ölçü: 128 × 128 mm\nDuş akış yüzeyi çapı: 80 mm\nPlaka kalınlığı: 7 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1900, 594, 'cs', 'Podomítkové boční masážní trysky', 'Podomítkové boční masážní trysky, úspora vody, masážní sprchové trysky, materiál ABS, čtvercový tvar, chromováno', 'Podomítkové boční masážní trysky, úspora vody, masážní sprchové trysky, materiál ABS, čtvercový tvar, chromováno\n\nOvěřené rozměry z technického výkresu:\nVnější rozměr: 145 × 145 mm\nCelková hloubka: 95 mm\nVnitřní rozměr: 128 × 128 mm\nPrůměr sprchové hlavice: 80 mm\nTloušťka desky: 7 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1901, 595, 'tr', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası, masif pirinç gövde yapısı, krom yüzey, kare tasarım, kumanda rozeti, seramik diskli kartuş, duvara monte, ankastre sıva altı gövdesi dahil.', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası, masif pirinç gövde yapısı, krom yüzey, kare tasarım, kumanda rozeti, seramik diskli kartuş, duvara monte, ankastre sıva altı gövdesi dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nDış ölçü: 120 × 120 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1902, 595, 'cs', 'Podomítková jednopáková sprchová baterie s přepínačem', 'Podomítková jednopáková sprchová baterie s přepínačem, masivní mosazná konstrukce, chromový povrch, čtvercový design, krycí rozeta, keramická disková kartuše, nástěnná montáž, včetně podomítkového tělesa.', 'Podomítková jednopáková sprchová baterie s přepínačem, masivní mosazná konstrukce, chromový povrch, čtvercový design, krycí rozeta, keramická disková kartuše, nástěnná montáž, včetně podomítkového tělesa.\n\nOvěřené rozměry z technického výkresu:\nVnější rozměr: 120 × 120 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1903, 596, 'tr', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası, masif pirinç gövde yapısı, fırçalanmış nikel yüzey, yuvarlak rozet, kumanda milli kol mekanizması, yönlendirici kumanda düğmesi, seramik diskli kartuş, duvara monte, ankastre sıva…', 'Yönlendiricili Tek Kollu Ankastre Duş Bataryası, masif pirinç gövde yapısı, fırçalanmış nikel yüzey, yuvarlak rozet, kumanda milli kol mekanizması, yönlendirici kumanda düğmesi, seramik diskli kartuş, duvara monte, ankastre sıva altı gövdesi dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nRozet plakası çapı: 80 mm\nToplam çıkıntı mesafesi: 42 mm\nKumanda aks aralığı: 68 mm\nPlaka kalınlığı: 2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1904, 596, 'cs', 'Podomítková jednopáková sprchová baterie s přepínačem', 'Podomítková jednopáková sprchová baterie s přepínačem, masivní mosazná konstrukce, povrch broušený nikl, kulatá rozeta, ovládací páka s vřetenem, přepínací knoflík, keramická disková kartuše, nástěnná montáž, včetně podomítkového…', 'Podomítková jednopáková sprchová baterie s přepínačem, masivní mosazná konstrukce, povrch broušený nikl, kulatá rozeta, ovládací páka s vřetenem, přepínací knoflík, keramická disková kartuše, nástěnná montáž, včetně podomítkového tělesa.\n\nOvěřené rozměry z technického výkresu:\nPrůměr krycí desky: 80 mm\nCelkové vyložení: 42 mm\nRozteč ovládání: 68 mm\nTloušťka desky: 2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1905, 597, 'tr', 'Tepe Duş Başlığı', 'Tepe Duş Başlığı, Yüzey: krom paslanmaz çelik, Form: Kare, Yüzey: çelik akış modu: yağmur akışı, kireç kırıcı sistem: Evet', 'Tepe Duş Başlığı, Yüzey: krom paslanmaz çelik, Form: Kare, Yüzey: çelik\nakış modu: yağmur akışı, kireç kırıcı sistem: Evet\n\nDoğrulanmış teknik çizim ölçüleri:\nDış ölçü: 300 × 300 mm\nToplam yükseklik: 55 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1906, 597, 'cs', 'Hlavová sprcha', 'Hlavová sprcha, Povrch: chromovaná nerezová ocel, Tvar: Čtvercový, Povrch: ocel režim proudu: dešťový proud, úprava proti vodnímu kameni: Ano', 'Hlavová sprcha, Povrch: chromovaná nerezová ocel, Tvar: Čtvercový, Povrch: ocel\nrežim proudu: dešťový proud, úprava proti vodnímu kameni: Ano\n\nOvěřené rozměry z technického výkresu:\nVnější rozměr: 300 × 300 mm\nCelková výška: 55 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1907, 598, 'tr', 'Tepe Duş Başlığı', 'Tepe Duş Başlığı, Yüzey: krom paslanmaz çelik, Form: Yuvarlak, Yüzey: çelik Malzeme: çelik 304 akış modu: yağmur akışı, kireç kırıcı sistem: Evet', 'Tepe Duş Başlığı, Yüzey: krom paslanmaz çelik, Form: Yuvarlak, Yüzey: çelik\nMalzeme: çelik 304\nakış modu: yağmur akışı, kireç kırıcı sistem: Evet\n\nDoğrulanmış teknik çizim ölçüleri:\nDış çap: 300 mm\nToplam yükseklik: 55 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1908, 598, 'cs', 'Hlavová sprcha', 'Hlavová sprcha, Povrch: chromovaná nerezová ocel, Tvar: Kulatý, Povrch: ocel Materiál: ocel 304 režim proudu: dešťový proud, úprava proti vodnímu kameni: Ano', 'Hlavová sprcha, Povrch: chromovaná nerezová ocel, Tvar: Kulatý, Povrch: ocel\nMateriál: ocel 304\nrežim proudu: dešťový proud, úprava proti vodnímu kameni: Ano\n\nOvěřené rozměry z technického výkresu:\nVnější průměr: 300 mm\nCelková výška: 55 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1909, 599, 'tr', 'Duş Çıkış Gagası', 'Duş Çıkış Gagası, duvara monte - Yüzey: krom gaga tipi: duvar duş çıkışı Malzeme: pirinç gaga tipi: sabit gaga', 'Duş Çıkış Gagası, duvara monte - Yüzey: krom\ngaga tipi: duvar duş çıkışı\nMalzeme: pirinç\ngaga tipi: sabit gaga\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 400 mm\nKol kesiti: 25 × 25 mm\nDuvar rozeti ölçüsü: 55 × 55 mm\nUç yüksekliği: 60 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1910, 599, 'cs', 'Sprchový výtok', 'Sprchový výtok, nástěnná montáž - Povrch: chrom typ výtoku: nástěnný sprchový vývod Materiál: mosaz typ výtoku: pevný výtok', 'Sprchový výtok, nástěnná montáž - Povrch: chrom\ntyp výtoku: nástěnný sprchový vývod\nMateriál: mosaz\ntyp výtoku: pevný výtok\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 400 mm\nProfil ramene: 25 × 25 mm\nNástěnná rozeta: 55 × 55 mm\nKoncová výška: 60 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1911, 600, 'tr', 'Tavan Tipi Duş Çıkış Borusu', 'Tavan Tipi Duş Çıkış Borusu, Yüzey: krom gaga tipi: duvar duş çıkışı Malzeme: pirinç gaga tipi: sabit gaga', 'Tavan Tipi Duş Çıkış Borusu, Yüzey: krom\ngaga tipi: duvar duş çıkışı\nMalzeme: pirinç\ngaga tipi: sabit gaga\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 200 mm\nKol kesiti: 25 × 25 mm\nDuvar rozeti ölçüsü: 50 × 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1912, 600, 'cs', 'Stropní sprchové rameno', 'Stropní sprchové rameno, Povrch: chrom typ výtoku: nástěnný sprchový vývod Materiál: mosaz typ výtoku: pevný výtok', 'Stropní sprchové rameno, Povrch: chrom\ntyp výtoku: nástěnný sprchový vývod\nMateriál: mosaz\ntyp výtoku: pevný výtok\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 200 mm\nProfil ramene: 25 × 25 mm\nNástěnná rozeta: 50 × 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1913, 601, 'tr', 'El Duşu Seti', 'El Duşu Seti, Montaj: duvara monte, Malzeme: pirinç ve ABS polimer, paslanmaz çelik, krom renk, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, akış modu: yağmur akışı', 'El Duşu Seti, Montaj: duvara monte, Malzeme: pirinç ve ABS polimer, paslanmaz çelik, krom renk, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, akış modu: yağmur akışı\n\nDoğrulanmış teknik çizim ölçüleri:\nEl duşu yüksekliği: 185 mm\nÜst çap: 28 mm\nBağlantı rakoru çapı: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1914, 601, 'cs', 'Souprava ruční sprchy', 'Souprava ruční sprchy, Montáž: nástěnná montáž, Materiál: mosaz a ABS plast, nerezová ocel, chrom, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, režim proudu: dešťový proud', 'Souprava ruční sprchy, Montáž: nástěnná montáž, Materiál: mosaz a ABS plast, nerezová ocel, chrom, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, režim proudu: dešťový proud\n\nOvěřené rozměry z technického výkresu:\nVýška ruční sprchy: 185 mm\nHorní průměr: 28 mm\nPrůměr přípojky: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1915, 602, 'tr', 'Duş Kolonu', 'Duş Kolonu, duş bataryalı, 3 yollu, Yüzey: krom, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları', 'Duş Kolonu, duş bataryalı, 3 yollu, Yüzey: krom, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları\n\nDoğrulanmış teknik çizim ölçüleri:\nAyarlanabilir toplam yükseklik: 850–1225 mm\nKol erişim mesafesi: 370 mm\nTepe duşu ölçüsü: 250 × 250 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1916, 602, 'cs', 'Sprchový sloup', 'Sprchový sloup, se sprchovou baterií, 3cestný, Povrch: chrom, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, odolné mosazné koncovky hadice', 'Sprchový sloup, se sprchovou baterií, 3cestný, Povrch: chrom, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, odolné mosazné koncovky hadice\n\nOvěřené rozměry z technického výkresu:\nNastavitelná celková výška: 850–1225 mm\nDosah ramene: 370 mm\nHlavová sprcha: 250 × 250 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1917, 603, 'tr', 'Duş Kolonu', 'Duş Kolonu, duş bataryasız, Yüzey: krom, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları', 'Duş Kolonu, duş bataryasız, Yüzey: krom, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları');
