INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1921, 605, 'tr', 'Duş Seti Sürgü Barı', 'Duş Seti Sürgü Barı, Montaj: duvara monte, Malzeme: pirinç ve ABS polimer, paslanmaz çelik, krom renk, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, ABS kumanda kolu', 'Duş Seti Sürgü Barı, Montaj: duvara monte, Malzeme: pirinç ve ABS polimer, paslanmaz çelik, krom renk, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, ABS kumanda kolu\n\nDoğrulanmış teknik çizim ölçüleri:\nÖn görünüm yüksekliği: 603 mm\nYan görünüm yüksekliği: 550 mm\nMaksimum çıkıntı mesafesi: 313 mm\nTepe duşu çapı: 100 mm\nHortum uzunluğu: 1750 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1922, 605, 'cs', 'Posuvná sprchová tyč', 'Posuvná sprchová tyč, Montáž: nástěnná montáž, Materiál: mosaz a ABS plast, nerezová ocel, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, ABS páčka', 'Posuvná sprchová tyč, Montáž: nástěnná montáž, Materiál: mosaz a ABS plast, nerezová ocel, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, ABS páčka\n\nOvěřené rozměry z technického výkresu:\nVýška v čelním pohledu: 603 mm\nVýška v bočním pohledu: 550 mm\nMaximální vyložení: 313 mm\nPrůměr hlavové sprchy: 100 mm\nDélka hadice: 1750 mm');
