INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1926, 607, 'cs', 'Podomítková sprchová souprava', 'Podomítková sprchová souprava, s posuvnou tyčí a sprchovou hlavicí, Povrch: chrom typ baterie: jednopáková, baterie způsob montáže: podomítková', 'Podomítková sprchová souprava, s posuvnou tyčí a sprchovou hlavicí, Povrch: chrom\ntyp baterie: jednopáková, baterie\nzpůsob montáže: podomítková');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1927, 608, 'tr', 'Ankastre Duş Seti', 'Ankastre Duş Seti, Yüzey: krom, batarya tipi: tek kollu, batarya montaj tipi: ankastre, ankastre sıva altı kutusu dahil', 'Ankastre Duş Seti, Yüzey: krom, batarya tipi: tek kollu, batarya\nmontaj tipi: ankastre, ankastre sıva altı kutusu dahil');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1928, 608, 'cs', 'Podomítková sprchová souprava', 'Podomítková sprchová souprava, Povrch: chrom, typ baterie: jednopáková, baterie způsob montáže: podomítková, včetně podomítkového boxu', 'Podomítková sprchová souprava, Povrch: chrom, typ baterie: jednopáková, baterie\nzpůsob montáže: podomítková, včetně podomítkového boxu');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1929, 609, 'tr', 'Ankastre Duş Seti', 'Ankastre Duş Seti, Yüzey: krom, tepe duşu: ultra ince yuvarlak tasarım, AISI 304 paslanmaz çelik, duvara monte, krom kaplamalı pirinç, tek kollu, yönlendiricili ankastre batarya montaj tipi: ankastre, Bağlantı: G1/2”, kireç kırıcı…', 'Ankastre Duş Seti, Yüzey: krom, tepe duşu: ultra ince yuvarlak tasarım, AISI 304 paslanmaz çelik, duvara monte, krom kaplamalı pirinç, tek kollu, yönlendiricili ankastre batarya\nmontaj tipi: ankastre, Bağlantı: G1/2”, kireç kırıcı silikon nozullarla donatılmıştır, ses azaltıcı izolasyon sistemi dahil\n\nDoğrulanmış teknik çizim ölçüleri:\nKol uzunluğu: 357 mm\nTepe duşu çapı: 230 mm\nKumanda paneli çapı: 115 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1930, 609, 'cs', 'Podomítková sprchová souprava', 'Podomítková sprchová souprava, Povrch: chrom, hlavová sprcha: ultratenká kulatá, nerezová ocel AISI 304, nástěnná montáž, chromovaná mosaz, jednopáková, podomítková baterie s přepínačem způsob montáže: podomítková, Připojení…', 'Podomítková sprchová souprava, Povrch: chrom, hlavová sprcha: ultratenká kulatá, nerezová ocel AISI 304, nástěnná montáž, chromovaná mosaz, jednopáková, podomítková baterie s přepínačem\nzpůsob montáže: podomítková, Připojení: G1/2”, vybaveno silikonovými tryskami proti vodnímu kameni, včetně systému tlumení hluku\n\nOvěřené rozměry z technického výkresu:\nDélka ramene: 357 mm\nPrůměr hlavové sprchy: 230 mm\nPrůměr ovládací rozety: 115 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1931, 610, 'tr', 'Engelli Uyumlu Ankastre Duş Bataryası Seti', 'Engelli Uyumlu Ankastre Duş Bataryası Seti, Yüzey: krom, pirinç borulu ve ABS başlıklı tepe duşu, 3 fonksiyonlu el duşlu', 'Engelli Uyumlu Ankastre Duş Bataryası Seti, Yüzey: krom, pirinç borulu ve ABS başlıklı tepe duşu, 3 fonksiyonlu el duşlu\n\nDoğrulanmış teknik çizim ölçüleri:\nKol uzunluğu: 245 mm\nDuvar rozeti çapı: 55 mm\nKumanda paneli çapı: 115 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1932, 610, 'cs', 'Bezbariérová podomítková sprchová souprava s baterií', 'Bezbariérová podomítková sprchová souprava s baterií, Povrch: chrom, hlavová sprcha s mosazným ramenem a ABS hlavicí, s třípolohovou ruční sprchou', 'Bezbariérová podomítková sprchová souprava s baterií, Povrch: chrom, hlavová sprcha s mosazným ramenem a ABS hlavicí, s třípolohovou ruční sprchou\n\nOvěřené rozměry z technického výkresu:\nDélka ramene: 245 mm\nPrůměr nástěnné rozety: 55 mm\nPrůměr ovládací rozety: 115 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1933, 611, 'tr', 'Duş Bataryası', 'Duş Bataryası, ankastre tip, Yüzey: krom, batarya tipi: batarya, tek kollu, montaj tipi: ankastre', 'Duş Bataryası, ankastre tip, Yüzey: krom, batarya tipi: batarya, tek kollu, montaj tipi: ankastre\n\nDoğrulanmış teknik çizim ölçüleri:\nKumanda paneli ölçüsü: 120 × 170 mm\nAyarlanabilir derinlik: 58–78 mm\nPlaka kalınlığı: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1934, 611, 'cs', 'Sprchová baterie', 'Sprchová baterie, podomítkové provedení, Povrch: chrom, typ baterie: baterie, jednopáková, způsob montáže: podomítková', 'Sprchová baterie, podomítkové provedení, Povrch: chrom, typ baterie: baterie, jednopáková, způsob montáže: podomítková\n\nOvěřené rozměry z technického výkresu:\nOvládací deska: 120 × 170 mm\nNastavitelná hloubka: 58–78 mm\nTloušťka desky: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1935, 612, 'tr', 'Dekoratif Tepe Duş Başlığı', 'Dekoratif Tepe Duş Başlığı, ankastre tip, Yüzey: krom, montaj tipi: ankastre', 'Dekoratif Tepe Duş Başlığı, ankastre tip, Yüzey: krom, montaj tipi: ankastre\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 96 mm\nGövde yüksekliği: 54 mm\nToplam genişlik: 47 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1936, 612, 'cs', 'Designová hlavová sprcha', 'Designová hlavová sprcha, podomítkové provedení, Povrch: chrom, způsob montáže: podomítková', 'Designová hlavová sprcha, podomítkové provedení, Povrch: chrom, způsob montáže: podomítková\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 96 mm\nVýška tělesa: 54 mm\nCelková šířka: 47 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1937, 613, 'tr', 'Dekoratif Tepe Duş Başlığı', 'Dekoratif Tepe Duş Başlığı, ankastre tip, Yüzey: krom, montaj tipi: ankastre', 'Dekoratif Tepe Duş Başlığı, ankastre tip, Yüzey: krom, montaj tipi: ankastre\n\nDoğrulanmış teknik çizim ölçüleri:\nGaga uzunluğu: 97.5 mm\nGövde uzunluğu: 76.5 mm\nÇıkış eksen mesafesi: 41.5 mm\nGövde çapı: 45.5 mm\nRozet çapı: 62 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1938, 613, 'cs', 'Designová hlavová sprcha', 'Designová hlavová sprcha, podomítkové provedení, Povrch: chrom, způsob montáže: podomítková', 'Designová hlavová sprcha, podomítkové provedení, Povrch: chrom, způsob montáže: podomítková\n\nOvěřené rozměry z technického výkresu:\nDélka výtoku: 97.5 mm\nDélka tělesa: 76.5 mm\nOdsazení odpadu: 41.5 mm\nPrůměr tělesa: 45.5 mm\nPrůměr rozety: 62 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1939, 614, 'tr', 'Ankastre Duş Seti', 'Ankastre Duş Seti, Yüzey: krom, pirinç borulu ve ABS başlıklı tepe duşu, 3 fonksiyonlu el duşlu', 'Ankastre Duş Seti, Yüzey: krom, pirinç borulu ve ABS başlıklı tepe duşu, 3 fonksiyonlu el duşlu\n\nDoğrulanmış teknik çizim ölçüleri:\nEl duşu yüksekliği: 185 mm\nÜst çap: 28 mm\nBağlantı rakoru çapı: 50 mm\nKumanda paneli ölçüsü: 120 × 170 mm\nAyarlanabilir derinlik: 58–78 mm\nPlaka kalınlığı: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1940, 614, 'cs', 'Podomítková sprchová souprava', 'Podomítková sprchová souprava, Povrch: chrom, hlavová sprcha s mosazným ramenem a ABS hlavicí, s třípolohovou ruční sprchou', 'Podomítková sprchová souprava, Povrch: chrom, hlavová sprcha s mosazným ramenem a ABS hlavicí, s třípolohovou ruční sprchou\n\nOvěřené rozměry z technického výkresu:\nVýška ruční sprchy: 185 mm\nHorní průměr: 28 mm\nPrůměr přípojky: 50 mm\nOvládací deska: 120 × 170 mm\nNastavitelná hloubka: 58–78 mm\nTloušťka desky: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1941, 615, 'tr', 'Küvet Bataryası ve El Duşu Seti', 'Küvet Bataryası ve El Duşu Seti, Malzeme: masif pirinç, 4 parçalı set, sıcak ve soğuk su, banyo ve duş batarya grubu, kartuş ömrü: 500000 çevrim', 'Küvet Bataryası ve El Duşu Seti, Malzeme: masif pirinç, 4 parçalı set, sıcak ve soğuk su, banyo ve duş batarya grubu, kartuş ömrü: 500000 çevrim');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1942, 615, 'cs', 'Vanová baterie se sprchovou soupravou', 'Vanová baterie se sprchovou soupravou, Materiál: masivní mosaz, 4dílná sada, teplá a studená voda, vanová a sprchová armatura, životnost kartuše: 500000 cyklů', 'Vanová baterie se sprchovou soupravou, Materiál: masivní mosaz, 4dílná sada, teplá a studená voda, vanová a sprchová armatura, životnost kartuše: 500000 cyklů');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1943, 616, 'tr', 'Ankastre Duş Bataryası', 'Ankastre Duş Bataryası, duvara monte batarya ile el duşu, ile dikdörtgen duvar aynası, çift su girişli (sıcak ve soğuk su), çift çıkışlı (el duşu + küvet gagası), duvar aynası üzerinde sabit küvet gagası ve el duşu askısı, ve duş…', 'Ankastre Duş Bataryası, duvara monte batarya ile el duşu, ile dikdörtgen duvar aynası, çift su girişli (sıcak ve soğuk\nsu), çift çıkışlı (el duşu + küvet gagası), duvar aynası üzerinde sabit küvet gagası ve el duşu askısı, ve duş hortumu, ankastre iç gövde ve koruma kutusuyla birlikte, krom kaplamalı pirinç.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 360.5 mm\nGaga çıkıntı mesafesi: 211 mm\nEl duşu yüksekliği: 186 mm\nTezgâh üstü gövde yüksekliği: 100 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1944, 616, 'cs', 'Podomítková sprchová baterie', 'Podomítková sprchová baterie, nástěnná montáž baterie s ruční sprcha, s obdélníková nástěnná rozeta, pro dva přívody (studená a teplá voda), dva výstupy (ruční sprcha + vanový výtok), vanový výtok i držák ruční sprchy integrovaný…', 'Podomítková sprchová baterie, nástěnná montáž baterie s ruční sprcha, s obdélníková nástěnná rozeta, pro dva přívody (studená a teplá\nvoda), dva výstupy (ruční sprcha + vanový výtok), vanový výtok i držák ruční sprchy integrovaný na nástěnné rozetě, a sprchová hadice, s podomítkovým tělesem a montážním boxem, chromovaná mosaz.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 360.5 mm\nVyložení výtoku: 211 mm\nVýška ruční sprchy: 186 mm\nVýška stojánkového tělesa: 100 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1945, 617, 'tr', 'Ankastre Duş Bataryası', 'Ankastre Duş Bataryası, seramik kartuşlu, el duşlu ve yağmur tepe duşlu modern duvar tipi pirinç ve paslanmaz çelik duş bataryası seti, çift çıkışlı (el duşu + küvet gagası), duvar aynası üzerinde sabit küvet gagası ve el duşu…', 'Ankastre Duş Bataryası, seramik kartuşlu, el duşlu ve yağmur tepe duşlu modern duvar tipi pirinç ve paslanmaz çelik duş bataryası seti, çift çıkışlı (el duşu + küvet gagası), duvar aynası üzerinde sabit küvet gagası ve el duşu askısı, ve duş hortumu, ankastre iç gövde ve koruma kutusuyla birlikte, krom kaplamalı pirinç, bronz yüzey.');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1946, 617, 'cs', 'Podomítková sprchová baterie', 'Podomítková sprchová baterie, nástěnná sprchová souprava s keramickou kartuší, ruční sprchou a dešťovou hlavovou sprchou z mosazi a nerezové oceli, dva výstupy (ruční sprcha + vanový výtok), vanový výtok i držák ruční sprchy…', 'Podomítková sprchová baterie, nástěnná sprchová souprava s keramickou kartuší, ruční sprchou a dešťovou hlavovou sprchou z mosazi a nerezové oceli, dva výstupy (ruční sprcha + vanový výtok), vanový výtok i držák ruční sprchy integrovaný na nástěnné rozetě, a sprchová hadice, s podomítkovým tělesem a montážním boxem, chromovaná mosaz, bronzový povrch.');
