INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1969, 629, 'tr', 'Krom Sürgülü El Duşu Seti', 'Krom Sürgülü El Duşu Seti, Montaj: duvara monte Malzeme: pirinç ve ABS polimer, paslanmaz çelik, krom çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, ABS kumanda kolu', 'Krom Sürgülü El Duşu Seti, Montaj: duvara monte\nMalzeme: pirinç ve ABS polimer, paslanmaz çelik, krom\nçelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, ABS kumanda kolu\n\nDoğrulanmış teknik çizim ölçüleri:\nDuş kolonu yüksekliği: 650 mm\nDuş kolonu boru çapı: 25 mm\nEl duşu çapı: 28 mm\nBağlantı rakoru çapı: 39 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1970, 629, 'cs', 'Chromovaná sprchová souprava s posuvnou tyčí', 'Chromovaná sprchová souprava s posuvnou tyčí, Montáž: nástěnná montáž Materiál: mosaz a ABS plast, nerezová ocel, chrom ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, ABS páčka', 'Chromovaná sprchová souprava s posuvnou tyčí, Montáž: nástěnná montáž\nMateriál: mosaz a ABS plast, nerezová ocel, chrom\nocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, ABS páčka\n\nOvěřené rozměry z technického výkresu:\nVýška sprchového sloupu: 650 mm\nPrůměr stoupací tyče: 25 mm\nPrůměr ruční sprchy: 28 mm\nPrůměr přípojky: 39 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1971, 630, 'tr', 'Bataryalı Duş Kolonu Seti', 'Bataryalı Duş Kolonu Seti, paslanmaz çelik, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları, ABS yağmur tepe duşu ve el duşu', 'Bataryalı Duş Kolonu Seti, paslanmaz çelik, krom, çelik bar, el işçiliği detaylar, dolanma önleyici sistem, hortumun dolanmasını önleyen döner sistem, dayanıklı pirinç hortum başlıkları, ABS yağmur tepe duşu ve el duşu\n\nDoğrulanmış teknik çizim ölçüleri:\nKol uzunluğu: 340 mm\nTepe duşu ölçüsü: 200 × 200 mm\nÜst kolon yüksekliği: 380 mm\nAlt kolon yüksekliği: 730 mm\nBatarya genişliği: 150 mm\nBatarya yüksekliği: 143 mm\nGaga uzanım mesafesi: 215 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1972, 630, 'cs', 'Sprchový sloup s baterií', 'Sprchový sloup s baterií, nerezová ocel, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, odolné mosazné koncovky hadice, ABS dešťová hlavová a ruční sprcha', 'Sprchový sloup s baterií, nerezová ocel, chrom, ocelová tyč, ručně zpracované prvky, systém proti překroucení, zabraňující překroucení hadice, odolné mosazné koncovky hadice, ABS dešťová hlavová a ruční sprcha\n\nOvěřené rozměry z technického výkresu:\nDélka ramene: 340 mm\nHlavová sprcha: 200 × 200 mm\nVýška horní stoupačky: 380 mm\nVýška spodní stoupačky: 730 mm\nŠířka baterie: 150 mm\nVýška baterie: 143 mm\nDosah výtoku: 215 mm');
