INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (1988, 638, 'cs', 'Bezpečnostní nouzová sprcha s oční sprchou', 'Bezpečnostní nouzová sprcha s oční sprchou, nerezová ocel, kombinovaná bezpečnostní a oční sprcha s nožním pedálem dle normy ANSI Z358.1 s 1/2" nerezovým kulovým ventilem AISI 304, sloupová oční a obličejová sprcha vybavená…', 'Bezpečnostní nouzová sprcha s oční sprchou, nerezová ocel, kombinovaná bezpečnostní a oční sprcha s nožním pedálem dle normy ANSI Z358.1 s 1/2" nerezovým kulovým ventilem AISI 304, sloupová oční a obličejová sprcha vybavená medicínskou hlavicí AXION MSR\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 2330 mm\nDosah sprchového ramene: 650 mm\nZákladní deska: 150 × 150 mm\nRozteč kotvení základny: 114 mm');
