INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2019, 654, 'tr', 'Premium Yüzey Montajlı Duş Kolonu Sistemi', 'Premium Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile PVD krom-nikel yüzey, dahil: yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve Bağlantı Hortumu…', 'Premium Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile PVD krom-nikel yüzey, dahil: yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve Bağlantı Hortumu. yüzey montajlı duvar tipi kurulum.\n\nDoğrulanmış teknik çizim ölçüleri:\nKol uzunluğu: 351 mm\nToplam yükseklik: 1180 mm\nBatarya genişliği: 273 mm');
