INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2059, 674, 'tr', 'Yüzey Montajlı Duş Kolonu Sistemi', 'Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile fırçalanmış nikel yüzey ve PVD nikel detay, dahil: kare yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve…', 'Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile fırçalanmış nikel yüzey ve PVD nikel detay, dahil: kare yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve Bağlantı Hortumu. yüzey montajlı duvar tipi kurulum.\n\nDoğrulanmış teknik çizim ölçüleri:\nAyarlanabilir toplam yükseklik: 877–1232 mm\nKol uzunluğu: 501 mm\nTepe duşu genişliği: 284 mm\nBatarya genişliği: 269 mm\nTaban derinliği: 86 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2060, 674, 'cs', 'Nástěnný sprchový systém', 'Nástěnný sprchový systém, tělo z masivní mosazi s broušený nikl s PVD niklovými detaily, včetně: čtvercová dešťová hlavová sprcha, ruční sprcha, dvoucestný přepínač, nastavitelný jezdec, keramická kartuše, a Flexibilní připojovací…', 'Nástěnný sprchový systém, tělo z masivní mosazi s broušený nikl s PVD niklovými detaily, včetně: čtvercová dešťová hlavová sprcha, ruční sprcha, dvoucestný přepínač, nastavitelný jezdec, keramická kartuše, a Flexibilní připojovací hadice. nástěnná přiznaná montáž.\n\nOvěřené rozměry z technického výkresu:\nNastavitelná celková výška: 877–1232 mm\nDélka ramene: 501 mm\nŠířka hlavové sprchy: 284 mm\nŠířka baterie: 269 mm\nHloubka základny: 86 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2061, 675, 'tr', 'Yüzey Montajlı Duş Kolonu Sistemi', 'Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile mat siyah yüzey ve PVD rose gold detay, dahil: kare yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve…', 'Yüzey Montajlı Duş Kolonu Sistemi, masif pirinç gövde ile mat siyah yüzey ve PVD rose gold detay, dahil: kare yağmur tepe duşu, el duşu, 2 yollu yönlendirici, ayarlanabilir sürgü mekanizması, seramik kartuş, ve Esnek Duş ve Bağlantı Hortumu. yüzey montajlı duvar tipi kurulum.\n\nDoğrulanmış teknik çizim ölçüleri:\nAyarlanabilir toplam yükseklik: 877–1232 mm\nKol uzunluğu: 501 mm\nTepe duşu genişliği: 284 mm\nBatarya genişliği: 269 mm\nTaban derinliği: 86 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2062, 675, 'cs', 'Nástěnný sprchový systém', 'Nástěnný sprchový systém, tělo z masivní mosazi s matná černá s detaily PVD růžové zlato, včetně: čtvercová dešťová hlavová sprcha, ruční sprcha, dvoucestný přepínač, nastavitelný jezdec, keramická kartuše, a Flexibilní připojovací…', 'Nástěnný sprchový systém, tělo z masivní mosazi s matná černá s detaily PVD růžové zlato, včetně: čtvercová dešťová hlavová sprcha, ruční sprcha, dvoucestný přepínač, nastavitelný jezdec, keramická kartuše, a Flexibilní připojovací hadice. nástěnná přiznaná montáž.\n\nOvěřené rozměry z technického výkresu:\nNastavitelná celková výška: 877–1232 mm\nDélka ramene: 501 mm\nŠířka hlavové sprchy: 284 mm\nŠířka baterie: 269 mm\nHloubka základny: 86 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2063, 676, 'tr', 'Tepe ve El Duşlu Yüzey Montajlı Duş Kolonu Sistemi', 'Tepe ve El Duşlu Yüzey Montajlı Duş Kolonu Sistemi, PVD rose gold kaplamalı birinci sınıf masif pirinç gövdeden üretilmiştir. 2 yollu yönlendiricili modern mimari tasarım, ayarlanabilir el duşu sürgüsü, seramik kartuş, ve yumuşak…', 'Tepe ve El Duşlu Yüzey Montajlı Duş Kolonu Sistemi, PVD rose gold kaplamalı birinci sınıf masif pirinç gövdeden üretilmiştir. 2 yollu yönlendiricili modern mimari tasarım, ayarlanabilir el duşu sürgüsü, seramik kartuş, ve yumuşak kumanda kolu hareketi. tam set içeriği: yağmur tepe duşu, el duşu, duş dirseği, batarya gövdesi, Esnek Duş ve Bağlantı Hortumu, duvar bağlantı rakorları, ve montaj aksesuarları.\n\nDoğrulanmış teknik çizim ölçüleri:\nÖn görünüm yüksekliği: 1150 mm\nYan görünüm yüksekliği: 950 mm\nKol uzunluğu: 380 mm\nTepe duşu çapı: 250 mm\nKumanda paneli çapı: 110 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2064, 676, 'cs', 'Nástěnný sprchový sloup s hlavovou a ruční sprchou', 'Nástěnný sprchový sloup s hlavovou a ruční sprchou, vyrobeno z prémiové masivní mosazi s povrchem PVD růžové zlato. moderní provedení s dvoucestným přepínačem, nastavitelný posuvný držák ruční sprchy, keramická kartuše, a plynulý…', 'Nástěnný sprchový sloup s hlavovou a ruční sprchou, vyrobeno z prémiové masivní mosazi s povrchem PVD růžové zlato. moderní provedení s dvoucestným přepínačem, nastavitelný posuvný držák ruční sprchy, keramická kartuše, a plynulý chod ovládací páky. kompletní sada obsahuje: dešťová hlavová sprcha, ruční sprcha, sprchové rameno, tělo baterie, Flexibilní připojovací hadice, nástěnné přípojky, a instalační příslušenství.\n\nOvěřené rozměry z technického výkresu:\nVýška v čelním pohledu: 1150 mm\nVýška v bočním pohledu: 950 mm\nDélka ramene: 380 mm\nPrůměr hlavové sprchy: 250 mm\nPrůměr ovládací rozety: 110 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2065, 677, 'tr', 'Termostatik Bataryalı Duş Kolonu Seti', 'Termostatik Bataryalı Duş Kolonu Seti, Malzeme: pirinç, montaj tipi: duvar montajı, Yüzey: bronz, perlatör tipi: Neoperl, kireç kırıcı sistem', 'Termostatik Bataryalı Duş Kolonu Seti, Malzeme: pirinç, montaj tipi: duvar montajı,\nYüzey: bronz, \nperlatör tipi: Neoperl, \nkireç kırıcı sistem');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2066, 677, 'cs', 'Sprchová souprava s termostatickou baterií', 'Sprchová souprava s termostatickou baterií, Materiál: mosaz, způsob montáže: nástěnná montáž, Povrch: bronz, typ perlátoru: Neoperl, úprava proti vodnímu kameni', 'Sprchová souprava s termostatickou baterií, Materiál: mosaz, způsob montáže: nástěnná montáž,\nPovrch: bronz, \ntyp perlátoru: Neoperl, \núprava proti vodnímu kameni');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2067, 678, 'tr', 'Çok Fonksiyonlu Duş Paneli Sistemi', 'Çok Fonksiyonlu Duş Paneli Sistemi, SUS304 paslanmaz çelik konstrüksiyon, fırçalanmış yüzey, duvara monte, yağmur tepe duşu fonksiyonlu, şelale ve yumuşak sprey akış fonksiyonları, piyano tuşlu akış seçici, termostatik sıcak-soğuk…', 'Çok Fonksiyonlu Duş Paneli Sistemi, SUS304 paslanmaz çelik konstrüksiyon, fırçalanmış yüzey, duvara monte, yağmur tepe duşu fonksiyonlu, şelale ve yumuşak sprey akış fonksiyonları, piyano tuşlu akış seçici, termostatik sıcak-soğuk batarya, esnek hortumlu el duşu, seramik kartuş ve eksiksiz montaj aksesuarları.\n\nDoğrulanmış teknik çizim ölçüleri:\nPanel yüksekliği: 813 mm\nPanel genişliği: 110 mm\nPanel derinliği: 72 mm\nKol uzunluğu: 450 mm\nTepe duşu çapı: 250 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2068, 678, 'cs', 'Multifunkční sprchový panelový systém', 'Multifunkční sprchový panelový systém, konstrukce z nerezové oceli SUS304, broušený povrch, nástěnná montáž, s funkcí dešťové sprchy, funkce vodopádu a jemného sprchového proudu, klávesový přepínač funkcí, termostatická směšovací…', 'Multifunkční sprchový panelový systém, konstrukce z nerezové oceli SUS304, broušený povrch, nástěnná montáž, s funkcí dešťové sprchy, funkce vodopádu a jemného sprchového proudu, klávesový přepínač funkcí, termostatická směšovací baterie, ruční sprcha s flexibilní hadicí, keramická kartuše a kompletní montážní příslušenství.\n\nOvěřené rozměry z technického výkresu:\nVýška panelu: 813 mm\nŠířka panelu: 110 mm\nHloubka panelu: 72 mm\nDélka ramene: 450 mm\nPrůměr hlavové sprchy: 250 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2069, 679, 'tr', 'Banyo Bataryası', 'Banyo Bataryası, solo (bağımsız duran), ile duş seti, Malzeme: pirinç Yüzey: krom, batarya tipi: tek kollu, batarya akustik sınıfı [dB]: II (20 < x ≤ 30) montaj tipi: yerden monte perlatör tipi: Neoperl, kireç kırıcı sistem', 'Banyo Bataryası, solo (bağımsız duran), ile duş seti, Malzeme: pirinç\nYüzey: krom, batarya tipi: tek kollu, batarya\nakustik sınıfı [dB]: II (20 < x ≤ 30)\nmontaj tipi: yerden monte\nperlatör tipi: Neoperl, kireç kırıcı sistem\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 1029 mm\nKol uzunluğu: 373 mm\nİç kol uzunluğu: 263 mm\nSürgü barı yüksekliği: 780 mm\nTaban çapı: 64 mm\nBoru çapı: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2070, 679, 'cs', 'Vanová baterie', 'Vanová baterie, volně stojící, s sprchová souprava, Materiál: mosaz Povrch: chrom, typ baterie: jednopáková, baterie akustická skupina [dB]: II (20 < x ≤ 30) způsob montáže: stojící provedení typ perlátoru: Neoperl, úprava proti…', 'Vanová baterie, volně stojící, s sprchová souprava, Materiál: mosaz\nPovrch: chrom, typ baterie: jednopáková, baterie\nakustická skupina [dB]: II (20 < x ≤ 30)\nzpůsob montáže: stojící provedení\ntyp perlátoru: Neoperl, úprava proti vodnímu kameni\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 1029 mm\nDélka ramene: 373 mm\nVnitřní délka ramene: 263 mm\nVýška posuvné tyče: 780 mm\nPrůměr základny: 64 mm\nPrůměr tyče: 50 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2071, 680, 'tr', 'Çocuklara Özel Tek Kollu Lavabo Bataryası', 'Çocuklara Özel Tek Kollu Lavabo Bataryası, tezgâh üstü, birinci sınıf kurşunsuz pirinç gövde, kraliyet mavisi yüzey, eksiksiz montaj kiti.', 'Çocuklara Özel Tek Kollu Lavabo Bataryası, tezgâh üstü, birinci sınıf kurşunsuz pirinç gövde, kraliyet mavisi yüzey, eksiksiz montaj kiti.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 170 mm\nGaga yan yüksekliği: 165 mm\nGövde yüksekliği: 130 mm\nGaga uzanım mesafesi: 74.5 mm\nToplam genişlik: 57 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2072, 680, 'cs', 'Dětská jednopáková umyvadlová baterie', 'Dětská jednopáková umyvadlová baterie, stojánková montáž, prémiové bezolovnaté mosazné tělo, královsky modrý povrch, kompletní montážní sada.', 'Dětská jednopáková umyvadlová baterie, stojánková montáž, prémiové bezolovnaté mosazné tělo, královsky modrý povrch, kompletní montážní sada.\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 170 mm\nBoční výška výtoku: 165 mm\nVýška tělesa: 130 mm\nDosah výtoku: 74.5 mm\nCelková šířka: 57 mm');
