INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2079, 684, 'tr', 'Tekli Havlu Askı Barı', 'Tekli Havlu Askı Barı, duvara monte, birinci sınıf pirinç gövde yapısı mavi PVD yüzey, korozyon ve paslanmaya dayanıklı gizli montaj sistemi eksiksiz montaj kiti ile.', 'Tekli Havlu Askı Barı, duvara monte, birinci sınıf pirinç gövde yapısı\nmavi PVD yüzey, korozyon ve paslanmaya dayanıklı\ngizli montaj sistemi\neksiksiz montaj kiti ile.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 670 mm\nToplam yükseklik: 49 mm\nÇıkıntı mesafesi: 45 mm\nBoru çapı: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2080, 684, 'cs', 'Jednoduchá tyč na ručníky', 'Jednoduchá tyč na ručníky, nástěnná montáž, prémiová mosazná konstrukce modrý PVD povrch, odolné vůči korozi a rzi systém skrytého upevnění s kompletní montážní sadou.', 'Jednoduchá tyč na ručníky, nástěnná montáž, prémiová mosazná konstrukce\nmodrý PVD povrch, odolné vůči korozi a rzi\nsystém skrytého upevnění\ns kompletní montážní sadou.\n\nOvěřené rozměry z technického výkresu:\nCelková délka: 670 mm\nCelková výška: 49 mm\nVyložení: 45 mm\nPrůměr tyče: 10 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2081, 685, 'tr', 'Tekli Havlu Askı Barı', 'Tekli Havlu Askı Barı, duvara monte, birinci sınıf pirinç gövde yapısı sarı PVD yüzey, korozyon ve paslanmaya dayanıklı gizli montaj sistemi eksiksiz montaj kiti ile.', 'Tekli Havlu Askı Barı, duvara monte, birinci sınıf pirinç gövde yapısı\nsarı PVD yüzey, korozyon ve paslanmaya dayanıklı\ngizli montaj sistemi\neksiksiz montaj kiti ile.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam uzunluk: 670 mm\nToplam yükseklik: 49 mm\nÇıkıntı mesafesi: 45 mm\nBoru çapı: 10 mm');
