INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2119, 704, 'tr', 'Paslanmaz Çelik İçme Suyu Sebili', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, entegre soğutucu ve filtre sistemi, SS304, Kalınlık: #1.0, anma gerilimi: 110/220V, Kapasite: 3L, filtre sistemi: GAC, Soğuk: 8Gal.', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, entegre soğutucu ve filtre sistemi, SS304, Kalınlık: #1.0, anma gerilimi: 110/220V, Kapasite: 3L, filtre sistemi: GAC, Soğuk: 8Gal.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 467 mm\nToplam derinlik: 483 mm\nÜst montaj yüksekliği: 1318.2 mm\nAskı braketi yüksekliği: 504.2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2120, 704, 'cs', 'Nerezová pítková fontána', 'Nerezová pítková fontána, nástěnná montáž, vestavěný chladič a filtrační systém, SS304, Tloušťka: #1.0, jmenovité napětí: 110/220V, Objem: 3L, filtrační systém: GAC, Studená: 8Gal.', 'Nerezová pítková fontána, nástěnná montáž, vestavěný chladič a filtrační systém, SS304, Tloušťka: #1.0, jmenovité napětí: 110/220V, Objem: 3L, filtrační systém: GAC, Studená: 8Gal.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 467 mm\nCelková hloubka: 483 mm\nHorní montážní výška: 1318.2 mm\nVýška montážní konzoly: 504.2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2121, 705, 'tr', 'Paslanmaz Çelik İçme Suyu Sebili', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, bakteriyostatik AISI 304 paslanmaz çelik, fıskiyeli su musluklu, 1,5" gider süzgeci ve bardak yıkama aparatı, anma gerilimi: 110/220V', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, bakteriyostatik AISI 304 paslanmaz çelik, fıskiyeli su musluklu, 1,5" gider süzgeci ve bardak yıkama aparatı, anma gerilimi: 110/220V');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2122, 705, 'cs', 'Nerezová pítková fontána', 'Nerezová pítková fontána, nástěnná montáž, bakteriostatická nerezová ocel AISI 304, s pítkovým ventilem, odpad 1,5" a oplachovač sklenic, jmenovité napětí: 110/220V', 'Nerezová pítková fontána, nástěnná montáž, bakteriostatická nerezová ocel AISI 304, s pítkovým ventilem, odpad 1,5" a oplachovač sklenic, jmenovité napětí: 110/220V');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2123, 706, 'tr', 'Paslanmaz Çelik İçme Suyu Sebili', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, entegre soğutucu ve filtre sistemi, SS304, Kalınlık: #1.0, anma gerilimi: 110/220V, Kapasite: 3L, filtre sistemi: GAC, Soğuk: 8Gal. filtre dahil, soğutma ünitesi ve uzatma modülü.', 'Paslanmaz Çelik İçme Suyu Sebili, duvara monte, entegre soğutucu ve filtre sistemi, SS304, Kalınlık: #1.0, anma gerilimi: 110/220V, Kapasite: 3L, filtre sistemi: GAC, Soğuk: 8Gal.\nfiltre dahil, soğutma ünitesi ve uzatma modülü.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 467 mm\nToplam derinlik: 483 mm\nÜst montaj yüksekliği: 1318.2 mm\nAskı braketi yüksekliği: 504.2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2124, 706, 'cs', 'Nerezová pítková fontána', 'Nerezová pítková fontána, nástěnná montáž, vestavěný chladič a filtrační systém, SS304, Tloušťka: #1.0, jmenovité napětí: 110/220V, Objem: 3L, filtrační systém: GAC, Studená: 8Gal. včetně filtru, chladicí systém a rozšiřující modul.', 'Nerezová pítková fontána, nástěnná montáž, vestavěný chladič a filtrační systém, SS304, Tloušťka: #1.0, jmenovité napětí: 110/220V, Objem: 3L, filtrační systém: GAC, Studená: 8Gal.\nvčetně filtru, chladicí systém a rozšiřující modul.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 467 mm\nCelková hloubka: 483 mm\nHorní montážní výška: 1318.2 mm\nVýška montážní konzoly: 504.2 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2125, 707, 'tr', 'Premium Yerden Monte İçme Suyu Sebili', 'AISI 304 paslanmaz çelikten üretilmiş premium yerden monte içme suyu sebili, dahili filtre ve soğutma sistemi entegreli, hairline saten fırçalanmış yüzey, krom fıskiyeli içme musluğu dahil, 1-1/2" gider çıkışı ve soğutma sistemi…', 'AISI 304 paslanmaz çelikten üretilmiş premium yerden monte içme suyu sebili, dahili filtre ve soğutma sistemi entegreli, hairline saten fırçalanmış yüzey, krom fıskiyeli içme musluğu dahil, 1-1/2" gider çıkışı ve soğutma sistemi, Filtreler, damlalık ve süzgeç, boru, batarya.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 475 mm\nToplam yükseklik: 473 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2126, 707, 'cs', 'Prémiová stojící pítková fontána', 'prémiová stojící pítková fontána vyrobená z nerezové oceli AISI 304, s vestavěným filtrem a chladicím systémem, jemně kartáčovaný saténový povrch, dodáváno včetně chromovaného pítkového ventilu, 1-1/2" odpadní vývod a chladicí…', 'prémiová stojící pítková fontána vyrobená z nerezové oceli AISI 304, s vestavěným filtrem a chladicím systémem, jemně kartáčovaný saténový povrch, dodáváno včetně chromovaného pítkového ventilu, 1-1/2" odpadní vývod a chladicí systém, Filtry, odkapávač a výpusť, trubka, baterie.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 475 mm\nCelková výška: 473 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2127, 708, 'tr', 'Premium Yerden Monte İçme Suyu Sebili', 'AISI 316 paslanmaz çelikten üretilmiş premium yerden monte içme suyu sebili, dahili filtre ve soğutma sistemi entegreli, hairline saten fırçalanmış yüzey, krom fıskiyeli içme musluğu dahil, 1-1/2" gider çıkışı ve soğutma sistemi…', 'AISI 316 paslanmaz çelikten üretilmiş premium yerden monte içme suyu sebili, dahili filtre ve soğutma sistemi entegreli, hairline saten fırçalanmış yüzey, krom fıskiyeli içme musluğu dahil, 1-1/2" gider çıkışı ve soğutma sistemi, Filtreler, damlalık ve süzgeç, boru, batarya.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam genişlik: 475 mm\nToplam yükseklik: 473 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2128, 708, 'cs', 'Prémiová stojící pítková fontána', 'prémiová stojící pítková fontána vyrobená z nerezové oceli AISI 316, s vestavěným filtrem a chladicím systémem, jemně kartáčovaný saténový povrch, dodáváno včetně chromovaného pítkového ventilu, 1-1/2" odpadní vývod a chladicí…', 'prémiová stojící pítková fontána vyrobená z nerezové oceli AISI 316, s vestavěným filtrem a chladicím systémem, jemně kartáčovaný saténový povrch, dodáváno včetně chromovaného pítkového ventilu, 1-1/2" odpadní vývod a chladicí systém, Filtry, odkapávač a výpusť, trubka, baterie.\n\nOvěřené rozměry z technického výkresu:\nCelková šířka: 475 mm\nCelková výška: 473 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2129, 709, 'tr', 'Paslanmaz Çelik İçme Suyu Sebili', 'Paslanmaz Çelik İçme Suyu Sebili, solo (bağımsız duran), ile Filtre ve soğutma sistemi, kademeli yükseklik ayarlı, gövde içi kaçak akım koruma şalteri (RCBO) dahil.', 'Paslanmaz Çelik İçme Suyu Sebili, solo (bağımsız duran), ile Filtre ve soğutma sistemi, kademeli yükseklik ayarlı, gövde içi kaçak akım koruma şalteri (RCBO) dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nSol görünüm lavabo yüksekliği: 950 mm\nÖn görünüm lavabo yüksekliği: 690 mm\nSağ görünüm lavabo yüksekliği: 850 mm\nÜst genişlik: 261.7 mm\nHazne dış çapı: 300 mm\nHazne iç çapı: 280 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2130, 709, 'cs', 'Nerezová pítková fontána', 'Nerezová pítková fontána, volně stojící, s Filtr a chladicí systém, s výškovým odstupňováním, včetně integrovaného proudového chrániče RCBO.', 'Nerezová pítková fontána, volně stojící, s Filtr a chladicí systém, s výškovým odstupňováním, včetně integrovaného proudového chrániče RCBO.\n\nOvěřené rozměry z technického výkresu:\nVýška umyvadla v bočním pohledu zleva: 950 mm\nVýška umyvadla zepředu: 690 mm\nVýška umyvadla v bočním pohledu zprava: 850 mm\nHorní šířka: 261.7 mm\nVnější průměr mísy: 300 mm\nVnitřní průměr mísy: 280 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2131, 710, 'tr', 'Çift Hazneli Paslanmaz Çelik Su Sebili', 'Çift Hazneli Paslanmaz Çelik Su Sebili, solo (bağımsız duran), ile Filtre ve soğutma sistemi, kademeli yükseklik ayarlı, gövde içi kaçak akım koruma şalteri (RCBO) dahil.', 'Çift Hazneli Paslanmaz Çelik Su Sebili, solo (bağımsız duran), ile Filtre ve soğutma sistemi, kademeli yükseklik ayarlı, gövde içi kaçak akım koruma şalteri (RCBO) dahil.\n\nDoğrulanmış teknik çizim ölçüleri:\nToplam yükseklik: 1200 mm\nÜst bölüm ölçüsü: 260 × 260 mm\nTaban çapı: 250 mm\nLavabo yüksekliği: 858 mm\nLavabo çıkıntı mesafesi: 337 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2132, 710, 'cs', 'Dvojitá nerezová pítková fontána', 'Dvojitá nerezová pítková fontána, volně stojící, s Filtr a chladicí systém, s výškovým odstupňováním, včetně integrovaného proudového chrániče RCBO.', 'Dvojitá nerezová pítková fontána, volně stojící, s Filtr a chladicí systém, s výškovým odstupňováním, včetně integrovaného proudového chrániče RCBO.\n\nOvěřené rozměry z technického výkresu:\nCelková výška: 1200 mm\nHorní část: 260 × 260 mm\nPrůměr základny: 250 mm\nVýška umyvadla: 858 mm\nVyložení umyvadla: 337 mm');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (2133, 711, 'tr', 'Paslanmaz Çelik İçme Suyu Sebili', 'Paslanmaz Çelik İçme Suyu Sebili, AISI 304 paslanmaz çelik, mat yüzey, solo (bağımsız duran), soğutucu gaz R600, soğutma gücü:58W/70W. çalışma gerilimi: 220V/50Hz. soğuk su kapasitesi: 4.5-5.5L/h. soğuk su çıkış sıcaklığı: 8-15℃…', 'Paslanmaz Çelik İçme Suyu Sebili, AISI 304 paslanmaz çelik, mat yüzey, solo (bağımsız duran), soğutucu gaz R600, soğutma gücü:58W/70W.\nçalışma gerilimi: 220V/50Hz.\nsoğuk su kapasitesi: 4.5-5.5L/h.\nsoğuk su çıkış sıcaklığı: 8-15℃\nFiltre: Opsiyonel.\n\nDoğrulanmış teknik çizim ölçüleri:\nÜst ünite çapı: 300 mm\nOrta üst ünite yüksekliği: 705 mm\nOrta hazne yüksekliği: 905 mm\nOrta alt panel yüksekliği: 720 mm\nYan üst ünite yüksekliği: 690 mm\nYan çıkıntı mesafesi: 500 mm\nSağ hazne yüksekliği: 520 mm');
